-- The catalog's first 44 entries: olympiads, contests, hackathons, startup programmes,
-- camps, internships, grants and courses open to the club's members, collected from official
-- sites and Kazakh news on 10 October 2026 (generated by scripts/catalog/build.mjs from the
-- lists next to it). Dates are filled only where an official page confirmed the current season;
-- otherwise dates_note says what is known. Entries the Hub has edited since are left alone.

insert into public.opportunities (key, title, kind, organizer, tracks, region, grade_min, grade_max,
  eligibility, team, fee, summary, description, how_to_apply, url, apply_url, deadline, starts_on,
  ends_on, dates_note, dates_verified, sources, notes, hidden)
values
  ('respa-informatics', 'Республиканская олимпиада по информатике (9–11 (12) классы)', 'olympiad', 'Министерство просвещения РК и РНПЦ «Дарын»; районный и областной этапы проводят отделы и управление образования вместе с региональным центром «Дарын»', array['algo'], 'kz', 9, 12, 'Учащиеся 9–11 (12) классов общеобразовательных школ Казахстана. По правилам районного этапа 2025–2026 сильных 8-классников могут допустить к участию по программе старшего класса. Ученик выступает только по одному предмету. На каждый следующий этап проходят победители предыдущего.', 'Индивидуально', 'Бесплатно: в опубликованных правилах взнос не предусмотрен', 'Главная государственная олимпиада по информатике в Казахстане: школьный → районный → областной → заключительный этап. Лучшие в финале попадают в национальный олимпийский резерв, из которого набирают сборные на международные олимпиады.', 'Олимпиада проходит в четыре этапа: школьный, районный (городской), областной и заключительный (республиканский); на каждый следующий этап проходят победители предыдущего. В 2025–2026 учебном году в школьном этапе по всем предметам участвовали 358 146 школьников, в заключительном — 1 636; финал по информатике и математике прошёл 19–24 марта 2026 года в Костанае, по информатике было 149 участников. Задания районного этапа готовит «Дарын»; задания и решения всех этапов потом публикуются на его сайте, а финальные туры транслируются на YouTube. На районном этапе победителями и призёрами становятся до 45% участников по каждому предмету и классу. По итогам финала лучших по информатике зачисляют в национальный олимпийский резерв, и они получают возможность представлять страну на международных олимпиадах. В разные годы победители получали также ректорские гранты вузов (например, КБТУ, КазНУ, Satbayev University). Готовиться лучше по заданиям прошлых лет со страницы олимпиады и регулярно решать задачи на C++ (CSES, Codeforces).', 'Онлайн-регистрации нет: участие начинается со школьного этапа в своей школе. Скажите учителю информатики, что хотите участвовать, и уточните сроки школьного и районного этапов в школе и в отделе образования Петропавловска. Дальше по этапам проходят победители.', 'https://daryn.kz/respa/', null, null, null, null, 'График на 2026–2027 на сайте «Дарына» ещё не опубликован. Для ориентира, сроки 2025–2026: районный этап (естественно-математическое направление) — 17 декабря 2025 г. (апелляция 18 декабря), областной — 5–9 января 2026 г., заключительный по информатике и математике — 19–24 марта 2026 г. (Костанай). В 2024–2025 финал по информатике прошёл 10–15 марта 2025 г. в Актау.', false, array['https://daryn.kz/respa/', 'https://daryn.kz/darynkz/darynkz-kalendar/daryn.php', 'https://drive.google.com/file/d/10O4oeniwQSTmZBw5vjnm5qUziZ67CUch/view', 'https://drive.google.com/file/d/1vCWhn6XNOklOq4n7lCv3cG3_mcGZXUnO/view', 'https://daryn.kz/aul-olimp/'], 'Для учеников сельских школ есть отдельная Республиканская олимпиада для сельских школ (9–11 (12) классы). Регистрация на 2026–2027 шла 14–20 сентября 2026 на smart.daryn.kz. Обладатели её дипломов I степени получают право выступить в заключительном этапе основной олимпиады. Есть ли там информатика, нужно проверить по правилам (https://daryn.kz/aul-olimp/).', false),
  ('respa-informatics-junior', 'Республиканская олимпиада по информатике для 7–8 классов', 'olympiad', 'РНПЦ «Дарын» (Минпросвещения РК); первые три этапа организуют управления образования и региональные центры «Дарын»', array['algo'], 'kz', 7, 8, 'Учащиеся 7 и 8 классов всех общеобразовательных школ Казахстана; 7 и 8 классы оцениваются отдельно. На районный этап проходят победители школьного, на областной — победители районного. В республиканский этап от области едет только один ученик на предмет в каждом классе — тот, у кого высший балл.', 'Индивидуально', 'Бесплатно: в правилах взнос не предусмотрен', 'Младшая республиканская олимпиада «Дарына» по 12 предметам, включая информатику, в четыре этапа: от школы до республики. Хороший первый шаг к основной олимпиаде 9–11 классов и к юниорской EJOI.', 'Олимпиада проходит в четыре этапа: школьный, районный (городской), областной и республиканский, в каждом по одному туру. Задания второго–четвёртого этапов составляет «Дарын». Информатика входит в естественно-математическое направление вместе с математикой, физикой, химией, биологией и географией. На каждом этапе победителями и призёрами становятся не более 45% участников по предмету и классу; им вручают дипломы I–III степени. Квота области на республиканский этап — 24 ученика: по одному победителю с наивысшим баллом по каждому из 12 предметов в 7 и в 8 классе. Значит, от СКО на финал по информатике едут всего два человека. Туры снимают на видео, республиканский этап транслируют на YouTube. Для подготовки разберите задания и решения прошлых лет со страницы олимпиады и тренируйтесь на задачах уровня Codeforces Div. 3/4 и AtCoder ABC.', 'Регистрации нет: участие начинается со школьного этапа. Попросите учителя информатики включить вас в школьный этап и следите за сроками районного этапа (в 2025–2026 он прошёл в начале декабря).', 'https://daryn.kz/resp-junior-olimpiad-ru/', null, null, null, null, 'Сроки 2026–2027 ещё не опубликованы. В 2025–2026: районный этап — 3 декабря 2025 г. (7 класс) и 4 декабря 2025 г. (8 класс), естественно-математические предметы в 10:00; областной — 6 февраля 2026 г.; заключительный — 19–22 мая 2026 г.', false, array['https://daryn.kz/resp-junior-olimpiad-ru/', 'https://drive.google.com/file/d/1vmXWLqxafWnUW9XHFxPAqoM5pvHFJmoy/view', 'https://daryn.kz/darynkz/darynkz-kalendar/daryn.php'], 'Правила на 2025–2026 «Дарын» утвердил 10.11.2025 (текст на казахском). Ученики, родившиеся в 2012 году и позже, по возрасту подходят для EJOI 2027, которая пройдёт в Казахстане.', false),
  ('izho-informatics', 'Международная Жаутыковская олимпиада (IZhO) — информатика', 'olympiad', 'Минпросвещения РК, РНПЦ «Дарын», НАО «Республиканская физико-математическая школа» (РФМШ)', array['algo'], 'kz', null, null, 'Командная олимпиада физико-математических школ. От Казахстана приглашают по одной сборной от каждой области и от городов Астана, Алматы и Шымкент, а также команды НИШ (3), РФМШ (4) и лицеев «Білім-инновация» (6). Ученики этих школ не могут выступать за другие команды. Ограничений по классам в опубликованных правилах нет; составы команд определяют по результатам предметных олимпиад.', 'Команда из 7 человек (3 по математике, 2 по физике, 2 по информатике) плюс руководители; зачёт личный по каждому предмету и общий рейтинг команд', 'Для казахстанских команд взноса нет; проезд, проживание и питание оплачивает направляющая сторона. Иностранные команды платят оргвзнос (в 2026 г. — 2 500 USD за команду, 500 USD за индивидуального участника)', 'Одна из самых престижных олимпиад региона: каждый январь в Алматы съезжаются сильнейшие физмат-школы примерно из 15 стран. По информатике два тура по 5 часов с задачами международного уровня.', 'IZhO проводится больше 20 лет (в 2026 году прошла XXII олимпиада) на базе Республиканской физико-математической школы в Алматы. По информатике два тура по 5 часов, задания составляет международное жюри. На олимпиаду 2026 года ожидали больше 700 школьников и 150 руководителей из 15 стран. Каждый предмет оценивается отдельно: победителями становятся до 50% участников (дипломы I–III степени, золотые, серебряные и бронзовые медали), все участники получают сертификаты, а команды ранжируются по сумме баллов. Казахстанские школьники попадают на олимпиаду в составе сборной своей области; для СКО это сборная области. Для подготовки пригодятся архив задач на izho.kz и задачи IOI/APIO.', 'Казахстанские школьники не регистрируются индивидуально. Нужно попасть в сборную СКО: хорошо выступить на районном и областном этапах республиканской олимпиады и ещё осенью узнать порядок отбора в областном центре «Дарын» или управлении образования СКО. Список казахстанских команд «Дарын» утверждает до 20 декабря.', 'https://izho.kz/', null, null, null, null, 'Сроки IZhO 2027 ещё не объявлены. IZhO 2026 прошла в Алматы 10–15 января 2026 г.: 10 января заезд и открытие, 11-го I тур, 12-го II тур, 14-го координация, 15-го закрытие. По правилам список казахстанских команд утверждают до 20 декабря предыдущего года.', false, array['https://izho.kz/', 'https://izho.kz/press-release-2026/', 'https://daryn.kz/pol514/ZhautyqOru.pdf', 'https://daryn.kz/zhautyk-ru/'], 'Индивидуальный онлайн-тур по информатике открыт только для иностранных участников. В правилах местом проведения указана Астана, но олимпиада 2026 года прошла в Алматы (РФМШ) — это нужно уточнить. Для учителей и тренеров при IZhO проводится конкурс IMPACT Olympiad (по правилам заявки принимают с 1 по 30 декабря на impact@fizmat.kz) — это может пригодиться тренерам клуба. Олимпиада «Шелковый путь», которую также проводит «Дарын», — математическая, не по информатике.', false),
  ('eurasian-team-olympiad', 'Евразийская командная олимпиада по информатике (страны ШОС) — отбор через интернет-тур ВКОШП', 'olympiad', 'РНПЦ «Дарын» вместе с Университетом ИТМО (жюри Всероссийской командной олимпиады школьников по программированию, ВКОШП)', array['algo'], 'kz', null, null, 'Команды из трёх школьников с руководителем (учителем или тренером); можно собрать команду из учеников одной школы или сборную. Ограничений по классам в правилах нет. В интернет-туре не может участвовать команда, в которой хотя бы один школьник уже выступал с правом отбора на региональной отборочной олимпиаде ВКОШП.', 'Команда из 3 человек за одним компьютером плюс аккредитованный руководитель', 'Взнос в правилах не упоминается. В 2025 г. проживание и питание финалистов в Алматы оплачивал «Дарын», а проезд и расходы руководителя — направляющая сторона', 'Командная олимпиада по программированию в формате ICPC: осенью отборочный интернет-тур из своей школы, затем финал в Алматы. Идеальный формат для клубных команд из трёх человек.', 'Отборочный интернет-тур длится 5 часов и проходит одновременно с командной олимпиадой Санкт-Петербурга на тех же задачах. Команда решает их в компьютерном классе школы на одном компьютере под присмотром аккредитованного преподавателя и записывает своё выступление для прокторинга. Бумажные материалы разрешены, а заготовленные электронные материалы и любые нейросети или ИИ-помощники запрещены; языки — C++17, Python 3, Java, C#, Pascal, D, Kotlin. Места распределяются по правилам ICPC: сначала по числу решённых задач, при равенстве — по штрафному времени (+20 минут за каждую неудачную попытку). Лучших из Казахстана, Кыргызстана и Таджикистана приглашают в финал в Алматы: в 2025 году там было 72 команды (216 школьников), а в 2023 и 2024 годах в финал проходили команды, решившие 6 и больше задач отбора. Победители получают дипломы Минпросвещения РК и медали (в 2025 году — 30 золотых, 54 серебряных и 87 бронзовых), а в 2022 году 15 казахстанских призёров получили гранты КБТУ. Готовиться стоит командными тренировками на прошлых контестах ВКОШП и в Codeforces Gym.', 'Руководитель (учитель или тренер клуба) заранее проходит аккредитацию на сайте ВКОШП и получает код. Затем команда регистрируется на интернет-тур с этим кодом не позднее чем за 3 дня до тура. Логины и пароли руководитель получает минимум за 2 часа до начала.', 'https://daryn.kz/evraziyskaya-olymp-inform-ru/', 'https://neerc.ifmo.ru/school/russia-team/registration.jsp', date '2026-11-12', date '2026-11-15', date '2026-12-12', 'По сайту ВКОШП (ИТМО): отборочный интернет-тур — 15 ноября 2026 г. в 12:00 МСК (14:00 по Астане), 5 часов; финал XXVII ВКОШП — 11–12 декабря 2026 г. в Санкт-Петербурге, Новосибирске, Сириусе и Алматы. Команду нужно зарегистрировать не позднее чем за 3 дня до тура, то есть примерно до 12 ноября. Отдельное письмо «Дарына» на 2026–2027 пока не опубликовано; в 2025 г. интернет-тур был 16 ноября, а финал в Алматы — 15–16 декабря 2025 г.', true, array['https://neerc.ifmo.ru/school/russia-team/index.html', 'https://neerc.ifmo.ru/school/russia-team/internet.html', 'https://neerc.ifmo.ru/school/russia-team/selection.html', 'https://neerc.ifmo.ru/school/russia-team/rules.html', 'https://daryn.kz/evraziyskaya-olymp-inform-ru/'], 'Самое подходящее для клуба соревнование в этом списке: команда из трёх участников, а тренер клуба выступает аккредитованным руководителем. Сколько команд пройдёт в финал, жюри решает после тура. Правила «Дарына»: https://daryn.kz/pol514/Evraziyskayaolympru.pdf.', false),
  ('ioi-team-kz', 'Национальная сборная Казахстана по информатике: путь на IOI 2027 и APIO', 'olympiad', 'РНПЦ «Дарын» (Минпросвещения РК); IOI 2027 принимает Hasso Plattner Institute (Потсдам, Германия)', array['algo'], 'intl', null, null, 'Школьники Казахстана из национального олимпийского резерва. По регламенту IOI участник должен учиться в средней школе страны между 1 сентября и 31 декабря года перед олимпиадой и быть не старше 20 лет на 1 июля года олимпиады. В команде страны до 4 человек.', 'Личный зачёт; сборная страны — до 4 участников', 'Отбор бесплатный; сборы олимпийского резерва организует «Дарын»', 'Вершина школьной информатики: через финал республиканской олимпиады — в олимпийский резерв, затем сборы и отбор в четвёрку на IOI. IOI 2027 пройдёт 12–19 сентября 2027 года в Потсдаме (Германия).', 'Казахстан выступает на IOI с 1998 года и всего завоевал 75 медалей; на IOI 2025 в Сукре (Боливия) сборная взяла три серебра и одну бронзу. Путь в сборную: призовое место на заключительном этапе республиканской олимпиады по информатике → национальный олимпийский резерв → учебно-тренировочные сборы и отбор. В 2026 году сборы по информатике для четырёх членов команды прошли 25 июня – 3 июля в Долгопрудном (Россия). Казахстанские школьники выступают и на Азиатско-Тихоокеанской олимпиаде APIO: в 2023 году её выиграл ученик РФМШ — второй победитель APIO в истории страны. IOI состоит из двух туров по 5 часов, в каждом по три задачи, и медали получают не больше половины участников. Подготовка занимает годы: CSES Problem Set, архивы IOI и APIO, рейтинговые раунды Codeforces.', 'Прямой заявки нет. Нужно пройти все этапы республиканской олимпиады по информатике (9–11 классы) и оказаться среди лучших на заключительном этапе. Тогда школьника зачисляют в олимпийский резерв и приглашают на сборы «Дарына».', 'https://daryn.kz/ioi/', null, null, date '2027-09-12', date '2027-09-19', 'Даты IOI 2027 (12–19 сентября 2027 г., HPI, Потсдам) подтверждены официальным сайтом ioi2027.de. IOI 2026 прошла в Узбекистане 9–16 августа 2026 г. Сроки отбора и сборов на сезон 2026–2027 «Дарын» ещё не опубликовал. Хозяина и даты APIO 2027 в официальных источниках найти не удалось. Дальше IOI примут Япония (2028), Болгария (2029) и Макао (2030).', true, array['https://ioi2027.de/', 'https://ioinformatics.org/', 'https://daryn.kz/ioi/', 'https://daryn.kz/uchebno-trenirovochnye-sbory/', 'https://drive.google.com/file/d/1T8cVwZw5UyOYQWk2fVMKal3PzOmJfvAN/view', 'https://daryn.kz/pol514/IOIru.pdf', 'https://newtimes.kz/obshchestvo/208839-kazakhstanskie-shkolniki-stali-prizerami-olimpiady-po-informatike', 'https://digitalbusiness.kz/2023-05-31/shkolnik-iz-almaty-vyigral-stal-luchshim-programmistom-v-azii-i-tihookeanskom-regione/'], 'Формат APIO и квоту Казахстана в открытых источниках подтвердить не удалось — их стоит уточнить в «Дарыне»; на сайтах IZhO и EJOI контакт по международным олимпиадам — daryn.intel@gmail.com. В 2024 году сборная перед IOI тренировалась 20–30 августа на базе МФТИ.', false),
  ('ejoi-2027', 'Европейская юниорская олимпиада по информатике EJOI 2027 (Бурабай, Казахстан)', 'olympiad', 'EJOI (Международный комитет); от Казахстана — РНПЦ «Дарын»', array['algo'], 'kz', 7, 9, 'Школьники не выше уровня среднего образования, родившиеся после 31 декабря 2011 года, то есть в 2012 году и позже (правило EJOI: младше 16 лет в год олимпиады). Классы 7–9 указаны примерно — решает дата рождения. От страны едут до 4 участников, отобранных по национальной олимпиаде.', 'Личный зачёт; национальная команда — до 4 участников и 2 руководителей', 'Отбор бесплатный; участвовать можно только в составе сборной', 'Юниорская версия IOI для школьников до 16 лет; в 2027 году она впервые пройдёт в Казахстане — в Бурабае, 2–8 августа. Реальная цель для сильных 7–9-классников клуба.', 'EJOI проводится с 2017 года по правилам и стандартам IOI: два соревновательных дня, в каждый — три задачи на 4 часа, а перед ними пробный тур. Писать можно только на C++; задачи даются на английском, руководители переводят их на родной язык. Медали получает примерно половина участников, золото, серебро и бронза делятся примерно как 1:2:3. Казахстан участвует с 2020 года: на EJOI 2026 в Каунасе (Литва, 24–30 июля) сборная взяла золото (ученик 8 класса РФМШ), серебро, бронзу и почётную грамоту. Команду Казахстана формируют из победителей и призёров республиканской олимпиады по информатике. Для подготовки подойдут Syllabus EJOI, архив прошлых олимпиад на eolymp и задачи CSES.', 'Прямой заявки нет: нужно стать победителем или призёром республиканской олимпиады по информатике и пройти отбор «Дарына». Какую олимпиаду (7–8 или 9–11 классов) учитывают при отборе на EJOI 2027, нужно уточнить в «Дарыне».', 'https://ejoi.org/', null, null, date '2027-08-02', date '2027-08-08', 'Даты и место EJOI 2027 (Бурабай, Казахстан, 2–8 августа 2027 г.) указаны в официальных данных сайта ejoi.org. Порядок и сроки национального отбора на 2027 год «Дарын» пока не опубликовал.', true, array['https://ejoi.org/', 'https://ejoi.org/data/editions.json', 'https://ejoi.org/data/countries.json', 'https://ejoi.org/data/regulations.json', 'https://www.zakon.kz/sobytiia/6526579-zoloto-serebro-i-bronza-sbornaya-kazakhstana-uspeshno-vystupila-na-EJOI-2026.html', 'https://daryn.kz/ejoi/', 'https://daryn.kz/pol514/EJOIinfru.pdf'], 'Возрастное правило: на EJOI 2027 могут поехать родившиеся в 2012 году и позже. Олимпиада проходит очно.', false),
  ('usaco', 'USACO — USA Computing Olympiad (онлайн-контесты)', 'competition', 'USA Computing Olympiad (USACO)', array['algo'], 'online', null, null, 'Участие бесплатное и открыто для всех, в том числе для школьников из Казахстана. Иностранцы решают онлайн-контесты и поднимаются по дивизионам, но в финальный лагерь и сборную США на IOI/EGOI отбирают только граждан или резидентов США.', 'Индивидуально', 'Бесплатно', 'Классические онлайн-олимпиады по алгоритмам с лестницей дивизионов Bronze → Silver → Gold → Platinum. Отличная цель на сезон для участников трека алгоритмов любого уровня.', 'USACO проводит несколько онлайн-контестов за сезон. Контест идёт около 4 часов, и начать его можно в любой момент с пятницы по понедельник — таймер запускается, когда открываешь задачи. Дивизионов четыре: Bronze для тех, кто недавно начал программировать, затем Silver, Gold и Platinum; кто набрал баллы выше порога, переходит в следующий дивизион. Заранее регистрироваться не нужно, достаточно аккаунта на сайте. В сезоне 2025–2026 было три онлайн-контеста в январе–феврале, а финальный US Open стал очным прокторируемым контестом только по приглашению для лучших участников из США. На сайте есть бесплатные учебные материалы и архив задач с разборами и автоматической проверкой — по нему удобнее всего готовиться.', 'Создать аккаунт на usaco.org (кнопка «Register for New Account»). Когда идёт контест, на главной странице появляется кнопка входа в него.', 'https://usaco.org/', null, null, null, null, 'Расписание сезона 2026–2027 ещё не опубликовано. В 2025–2026: 1-й контест — 9–12 января 2026 г., 2-й — 30 января – 2 февраля, 3-й — 20–23 февраля, US Open (очный, по приглашению) — 28 марта 2026 г.', false, array['https://usaco.org/', 'https://usaco.org/index.php?page=details'], 'Организаторы называют сезон 2025–2026 переходным и могут изменить структуру дивизионов — формат стоит перепроверить, когда выйдет расписание 2026–2027.', false),
  ('codeforces', 'Раунды Codeforces', 'competition', 'Codeforces', array['algo'], 'online', null, null, 'Открыто для всех, нужен бесплатный аккаунт. Дивизион зависит от рейтинга: новичкам подходят Div. 4 и Div. 3, затем Div. 2.', 'Индивидуально', 'Бесплатно', 'Главная площадка спортивного программирования: несколько рейтинговых раундов в неделю. Основа регулярной практики для трека алгоритмов.', 'На Codeforces регулярно идут раунды Div. 1–4, Educational и Global, а также раунды по задачам национальных олимпиад; обычно раунд длится 2–3 часа. После каждого рейтингового раунда рейтинг пересчитывается, и по нему удобно следить за прогрессом участников клуба. На каждый раунд нужно заранее зарегистрироваться на странице соревнований. После раунда публикуются разборы, а весь архив задач можно решать в любое время. Для клубных тренировок полезны виртуальное участие в прошлых раундах и раздел тренировок (Gym) с олимпиадными контестами.', 'Зарегистрироваться на codeforces.com и записываться на каждый раунд на странице «Соревнования».', 'https://codeforces.com/contests', 'https://codeforces.com/register', null, null, null, 'Проходят постоянно, несколько раундов в неделю. Ближайшие на момент проверки (по Астане, UTC+5): Educational Codeforces Round 195 — 14 октября 2026, 19:35; WorldQuant Round 1 (Div. 1 + Div. 2) — 17 октября 2026, 19:35. Актуальное расписание — на странице соревнований.', false, array['https://codeforces.com/contests', 'https://codeforces.com/api/contest.list'], 'Часть раундов начинается поздно вечером по казахстанскому времени (например, в 23:35). Младшим участникам лучше выбирать раунды в 19:35 или решать прошедшие раунды виртуально.', false),
  ('atcoder', 'AtCoder Beginner Contest (ABC) и другие контесты AtCoder', 'competition', 'AtCoder Inc. (Япония)', array['algo'], 'online', null, null, 'Открыто для всех, нужен бесплатный аккаунт. ABC идёт в рейтинг для участников с рейтингом до 1999.', 'Индивидуально', 'Бесплатно', 'Еженедельный контест для начинающих и среднего уровня: 100 минут, задачи от простых к сложным. Хорошая регулярная практика по выходным.', 'ABC проходит почти каждые выходные в 21:00 по японскому времени — это 17:00 по Астане, удобное время для школьников. Контест длится 1 час 40 минут, задачи идут по возрастанию сложности, условия есть на английском. Для участников посильнее есть AtCoder Regular Contest (ARC, рейтинг 1600–2999), Grand Contest (AGC, от 2000) и эвристические контесты AHC. Кроме того, проводятся ежедневные короткие нерейтинговые AtCoder Weekday Contest (Beta): 1 час, 20:00 JST, то есть 16:00 по Астане. После контестов выходят разборы, а архив AtCoder очень хорош для отработки базовых алгоритмов и математики.', 'Зарегистрироваться на atcoder.jp и до начала нажать «Register» на странице нужного контеста.', 'https://atcoder.jp/contests/', null, null, null, null, 'Проходят постоянно, почти каждые выходные. Ближайшие на момент проверки: ABC 479 — 11 октября 2026, 21:00 JST (17:00 по Астане); ABC 480 — 17 октября 2026, 21:00 JST; ARC 232 — 10 октября 2026; AGC 079 — 8 ноября 2026.', false, array['https://atcoder.jp/contests/?lang=en'], 'Хорошо дополняет Codeforces: ABC в 17:00 по Астане удобнее поздних раундов Codeforces.', false),
  ('innopolis-open', 'Innopolis Open — Международная олимпиада Иннополиса по информатике', 'olympiad', 'Университет Иннополис (Россия)', array['algo'], 'online', 7, 12, 'Учащиеся 7–11 (12) классов и студенты 1–2 курсов колледжей из России и других стран, в том числе из Казахстана. Участие индивидуальное.', 'Индивидуально', 'Бесплатно', 'Крупная международная олимпиада по программированию (больше 5000 участников в год): два независимых онлайн-отбора и очный финал. Регистрация на сезон 2026–2027 открыта до 19 октября 2026 года.', 'Отбор состоит из двух независимых онлайн-туров: чтобы выйти в финал, достаточно стать победителем или призёром любого из них, причём проходные баллы могут различаться. В отборочном туре 3–5 задач, а перед каждым туром проводится пробный, чтобы привыкнуть к платформе. Финал проходит очно в Университете Иннополис и на других площадках, список которых объявят позже; в финале 3–7 задач разной сложности. Олимпиада входит в перечень РСОШ, поэтому её дипломы дают льготы при поступлении в российские вузы, а в Университет Иннополис — дополнительные бонусы. На странице олимпиады выложены условия, разборы и результаты прошлых лет на русском и английском — это лучший материал для подготовки.', 'Зарегистрироваться на профиль «Информатика» через личный кабинет на странице олимпиады до 19 октября 2026 г., 15:00 МСК (17:00 по Астане). Накануне тура на почту придёт инструкция по платформе.', 'https://dovuz.innopolis.university/pre-olympiads/innopolis-open/informatics', null, date '2026-10-19', date '2026-10-30', date '2027-02-14', 'По предварительному расписанию на официальном сайте: регистрация с 15 сентября до 19 октября 2026 г. (15:00 МСК); 1-й отборочный тур — 30–31 октября 2026 г. (30-го пробный, 31-го основной), 2-й — 25–26 декабря 2026 г., оба онлайн; финал — 12–14 февраля 2027 г., очно. Даты могут уточняться.', true, array['https://dovuz.innopolis.university/pre-olympiads/innopolis-open/informatics', 'https://dovuz.innopolis.university/innopolis-open'], 'Отборы проходят онлайн, а на финал нужно ехать на одну из площадок (их список ещё не объявлен). На странице профиля указан I уровень РСОШ, а на общей странице олимпиады — II; если это важно для поступления в российский вуз, уровень нужно уточнить.', false),
  ('tuymaada-informatics', 'Международная олимпиада «Туймаада» — информатика (Якутия)', 'olympiad', 'Министерство образования и науки Республики Саха (Якутия), Малая академия наук РС(Я), СВФУ им. М.К. Аммосова; новости об участии Казахстана публикует РНПЦ «Дарын»', array['algo'], 'intl', null, null, 'Школьники и выпускники текущего года из России и зарубежных стран, которых допустил оргкомитет. По информатике возрастных лиг нет. Казахстан участвует с 2004 года.', 'Личный зачёт; участники приезжают делегациями с руководителями', 'Оргвзнос за каждого участника и руководителя (размер устанавливается ежегодно); проезд, проживание и питание оплачивает направляющая сторона. Организаторы оплачивают проживание и питание не более чем одному победителю или призёру региональных, национальных или международных олимпиад от страны в каждой лиге каждого предмета', 'Летняя международная олимпиада в Якутии по математике, физике, химии и информатике; задачи по информатике — уровня международных олимпиад. Казахстан каждый год отправляет большую делегацию.', 'Олимпиада проводится ежегодно с 1994 года на базе Малой академии наук Республики Саха (Якутия) в селе Чапаево. По информатике два тура в разные дни, в каждом 3–4 задачи на 5 часов, у каждого участника свой компьютер; задания соответствуют программе международных олимпиад. Рабочий язык — русский, иностранцам дают официальный перевод на английский. Победители получают золотые, серебряные и бронзовые медали, абсолютный победитель — кубок. На 30-й олимпиаде Казахстан представляли 80 школьников из разных регионов, они завоевали 4 золотые, 14 серебряных и 15 бронзовых медалей (по всем предметам). Для подготовки подойдут задачи прошлых лет и контесты уровня Codeforces Div. 2/Div. 1.', 'Заявку по установленной форме подаёт направляющая организация (школа, управление образования или «Дарын») до 31 мая. Оргкомитет рассылает приглашения до 5 июня, а оргвзнос и копии паспортов нужно прислать до 15 июня (по положению). О наборе в казахстанскую делегацию спрашивайте в областном центре «Дарын».', 'https://daryn.kz/tuimada-ru/', null, null, null, null, 'Сроки 2027 года ещё не объявлены. В 2026 году олимпиада прошла 2–10 июля (календарь «Дарына»). По положению заявки принимают до 31 мая текущего года.', false, array['https://daryn.kz/tuimada-ru/', 'https://daryn.kz/pol514/Tuymadaru.pdf', 'https://daryn.kz/darynkz/darynkz-kalendar/daryn.php'], 'Положение на сайте «Дарына» — старая редакция; условия и размер взноса нужно сверить с информационным письмом текущего года.', false),
  ('ioai-2027', 'Международная олимпиада по искусственному интеллекту IOAI 2027 (Сингапур)', 'olympiad', 'IOAI; хозяева 2027 года — AI Singapore и Наньянский технологический университет (NTU). В Казахстане аккредитованная организация, отбирающая сборную, — Федерация спортивного программирования Казахстана (CPFED)', array['ai'], 'intl', 9, 12, 'По правилам IOAI 2026 участнику должно быть не больше 20 лет на 1 июля года олимпиады, и он должен учиться очно в школе (на 1 декабря предыдущего года или позже). Индивидуальной регистрации нет, только в составе национальной сборной. В Казахстане сборную отбирает CPFED через олимпиаду AI Olymp (9–12 классы) и учебно-тренировочные сборы, поэтому на практике путь открыт ученикам 9–12 классов.', 'Национальная команда: 4 участника и руководитель. В таймлайне IOAI 2027 сказано: «только одна команда от страны» (в 2026 году разрешалось до двух).', 'Отдельного взноса со школьника нет: командный взнос платит национальная организация (в 2026 году — от 1550 евро за команду при ранней регистрации). Подготовку и поездки сборной Казахстана поддерживает генеральный партнёр CPFED — Kaspi.kz.', 'Главная международная олимпиада школьников по ИИ и машинному обучению. Четвёртая IOAI пройдёт 4–10 июля 2027 года в Сингапуре.', 'IOAI проводится ежегодно с 2024 года: в 2025 году олимпиада прошла в Пекине, в 2026-м — в Астане (около 500 школьников из 106 стран). В 2026 году индивидуальный тур длился два дня, в нём было шесть задач по машинному обучению, компьютерному зрению, обработке естественного языка и мультимодальным моделям; был и командный тур. Формат 2027 года организаторы пока не объявили. В 2026 году все 8 участников сборной Казахстана завоевали медали, 2 из них — золотые. Для подготовки есть официальная программа (syllabus) на сайте IOAI и задачи прошлых лет в GitHub-репозитории ioai-official. Нужны уверенный Python, классическое ML, PyTorch, основы компьютерного зрения и NLP. Хорошая практика — соревнования Kaggle и олимпиада FAIO.', 'Сами школьники на IOAI не регистрируются. Нужно создать аккаунт на cpfed.kz, пройти AI Olymp (онлайн-отбор и финал), попасть на сборы и затем в сборную. Анонсы отбора публикуются в новостях cpfed.kz.', 'https://ioai-official.org/singapore-2027/', null, null, date '2027-07-04', date '2027-07-10', 'Даты 4–10 июля 2027 года подтверждены на ioai-official.org и сайте NTU. По официальному таймлайну национальный этап нужно провести не позднее 1 апреля 2027 года, а состав сборной утвердить к 15 апреля 2027 года. Даты казахстанского отбора на цикл 2027 года CPFED пока не объявила.', true, array['https://ioai-official.org/singapore-2027/', 'https://ioai-official.org/singapore-2027/ioai-2027-timeline/', 'https://www.ntu.edu.sg/news/detail/ntu-singapore-and-ai-singapore-to-host-2027-international-olympiad-in-artificial-intelligence', 'https://ioai-official.org/registration-2026/', 'https://ioai-official.org/about/countries-and-territories/', 'https://cpfed.kz/projects/tournaments/ioai', 'https://cpfed.kz/news'], 'Из-за лимита в одну команду в 2027 году у Казахстана, скорее всего, будет 4 места вместо 8 в 2026-м, так что конкуренция за сборную вырастет. Не путать с IAIO: это другая олимпиада.', false),
  ('ai-olymp', 'AI Olymp — республиканская олимпиада по искусственному интеллекту (отбор на IOAI)', 'olympiad', 'Федерация спортивного программирования Казахстана (CPFED) и сообщество DSML.KZ при поддержке Министерства цифрового развития, инноваций и аэрокосмической промышленности и Министерства просвещения РК', array['ai', 'algo'], 'kz', 9, 12, 'Школьники 9–12 классов из всех регионов Казахстана. Ученикам 7–8 классов участвовать пока рано, но к олимпиаде стоит готовиться заранее.', 'Индивидуальное участие', 'Бесплатно (по словам CPFED, все её отборочные турниры бесплатные)', 'Главная школьная олимпиада Казахстана по ИИ и машинному обучению и первый этап отбора в национальную сборную на IOAI. Проводится с 2025 года.', 'Олимпиада проходит в два этапа. Сначала онлайн-отбор с задачами по программированию, математике и классическому машинному обучению, затем очный финал в Астане для 40 лучших участников: в 2025 и 2026 годах он проходил в Astana IT University и состоял из двух туров. Победители получают дипломы I–III степени и медали. В 2026 году заявки подали более 500 школьников, медали получили 23 человека, а компания Documentolog пригласила победителей на стажировку. 12 лучших участников приглашают на учебно-тренировочные сборы, по их итогам формируется сборная на IOAI (в 2026 году — 8 человек); сборная также выступает на европейской олимпиаде EUROAI. Для подготовки нужны Python (numpy, pandas, scikit-learn), основы математики и статистики, классическое ML. Полезны открытые контесты CPFED и задачи IOAI и FAIO прошлых лет.', 'Создать аккаунт на cpfed.kz и зарегистрироваться на AI Olymp, когда откроется регистрация. Анонсы публикуются в разделе новостей cpfed.kz.', 'https://cpfed.kz/', null, null, null, null, 'Даты AI Olymp 2027 официально не объявлены: на 10 октября 2026 в новостях CPFED анонса нет. Для ориентира: в 2026 году онлайн-отбор прошёл 22 февраля (по данным Tengrinews), итоги финала CPFED опубликовала 16 апреля, а состав сборной объявили в июле. По таймлайну IOAI 2027 национальный отбор должен завершиться не позднее 1 апреля 2027 года.', false, array['https://cpfed.kz/news/ai-olymp-2026', 'https://cpfed.kz/news', 'https://the-tech.kz/?p=27943', 'https://tengrinews.kz/kazakhstan_news/novyie-it-proektyi-dlya-shkolnikov-startuyut-v-kazahstane-592027/', 'https://tengrinews.kz/kazakhstan_news/kaspikz-podderjivaet-sbornuyu-kazahstana-ii-gotovyat-604440/', 'https://24.kz/ru/news/obrazovanie-i-nauka/763125-nagrazhdeny-pobediteli-respublikanskoj-olimpiady-po-ii', 'https://ioai-official.org/singapore-2027/ioai-2027-timeline/'], 'Отдельной страницы AI Olymp на cpfed.kz нет, сведения взяты из новостей CPFED и СМИ. В 2027 году на IOAI, по таймлайну, поедет одна команда (4 человека). Открытые контесты CPFED (например, Div-2) доступны с 14 лет.', false),
  ('iaio-2027', 'International Artificial Intelligence Olympiad (IAIO 2027), Вьетнам', 'olympiad', 'IAIO; организаторы IAIO 2026 — IRCAI (International Research Centre on Artificial Intelligence, Любляна) совместно с ACM Slovenia; хозяин IAIO 2027 — Вьетнам', array['ai'], 'intl', null, null, 'Старшеклассники, победившие в национальных соревнованиях по ИИ в странах — членах IAIO. Казахстана на 10 октября 2026 нет в списке стран-членов, в IAIO 2026 он не участвовал, так что прямого пути для школьника из Казахстана сейчас нет. Возрастных ограничений официальный сайт не публикует.', 'Национальные делегации стран-членов (в 2026 году, например, Кыргызстан привёз 4 участников); туры проходят индивидуально.', 'На официальном сайте не указан', 'Международная олимпиада по ИИ для старшеклассников, не связанная с IOAI. IAIO 2027 пройдёт с 25 февраля по 2 марта 2027 года во Вьетнаме.', 'IAIO проводится с 2024 года: первая олимпиада прошла осенью 2024 года в Эр-Рияде, вторая — 23–27 февраля 2026 года в Любляне (98 школьников из 24 стран). Соревнование состоит из научного тура с теоретическими задачами по математике, логике, физике и data science и практического тура на платформе Zindi; в 2024 году каждый тур длился 5 часов, практический решался на Python на подготовленных ноутбуках с ограниченным доступом в интернет. Призёры получают золотые, серебряные и бронзовые медали, есть почётные грамоты. Это не IOAI и не отбор на неё: у IAIO свой состав стран (около 40 членов, среди них Кыргызстан и Россия). Организация из Казахстана (вуз, школа, НКО) может подать на сайте IAIO заявку на членство; это единственный путь, если кто-то захочет открыть участие для казахстанских школьников. Для подготовки подходят материалы IOAI, вебинары на сайте IAIO и соревнования Zindi.', 'Индивидуальной регистрации нет. Участвовать можно только через национальную организацию — члена IAIO; организации подают заявку на членство на iaio-official.org (раздел Apply for Membership).', 'https://www.iaio-official.org/', null, null, date '2027-02-25', date '2027-03-02', 'Даты 25 февраля – 2 марта 2027 года и страна-хозяйка (Вьетнам) указаны на официальном сайте IAIO; город и формат пока не объявлены. Сроков регистрации делегаций на сайте нет.', true, array['https://www.iaio-official.org/', 'https://www.iaio-official.org/member-countries/', 'https://www.iaio-official.org/competition/', 'https://iaio-official.org/results2026/', 'https://ircai.org/iaio-2026-successfully-concluded-ircai-supports-the-next-generation-of-responsible-ai-professionals/', 'https://ircai.org/ircai-hosts-international-winter-ai-olympiad-in-ljubljana/'], 'Не путать с IOAI (ioai-official.org). Для участников из Казахстана сейчас фактически недоступна; запись оставлена для справки.', false),
  ('faio', 'FAIO — International AI Olympiad in Kazakhstan (Fizmat, Алматы)', 'olympiad', 'Fizmat — National School of Physics and Mathematics (NSPM), Алматы', array['ai', 'algo'], 'kz', null, null, 'Школьники из Казахстана и других стран; ограничений по классам на сайте нет. Опыт в машинном обучении не обязателен, нужная теория даётся в условиях задач. Если команда едет на финал без сопровождающего взрослого, всем её участникам должно быть не меньше 16 лет и нужно нотариальное согласие родителей.', 'Команда из 1–3 человек; на финал команда едет в том составе, в котором прошла отбор, добавлять участников нельзя.', 'Бесплатно. Финалистам организаторы оплачивают трансфер, проживание с 26 по 30 октября и питание (участникам и одному сопровождающему); дорогу до Алматы оплачивает направляющая сторона.', 'Командная олимпиада по машинному обучению, программированию и математике от алматинского Fizmat; с 2025 года международная.', 'FAIO впервые прошла в 2024 году как первая в стране ML-олимпиада для школьников, в 2025 году стала международной. В 2026 году в отборе участвовали школьники из 28 стран, в финале — из 25. Формат: онлайн-отбор (4 часа) и очный финал в Алматы — два тура по 5 часов с теоретическими и практическими задачами по ML, анализу данных, математике и программированию. Дипломы I–III степени получают не более 50% финалистов, все участники получают сертификаты, призовой фонд объявляют перед финалом. Цикл 2026 года уже идёт: регистрация закрыта, отбор прошёл 20 сентября, финал — 27–28 октября. Следующая олимпиада будет в 2027 году; готовиться к ней стоит по задачам прошлых лет (GitHub-репозиторий faio-tasks), книге mlcourse.ai и задачам IOAI.', 'Регистрация на 2026 год закрыта. Чтобы не пропустить FAIO 2027, подпишитесь на Telegram-канал t.me/faiokz и следите за сайтом faio.kz.', 'https://faio.kz/', null, null, date '2026-10-27', date '2026-10-28', 'Указаны даты туров финала FAIO 2026 (заезд 26 октября, закрытие 29 октября, Алматы) по официальной странице faio.kz/final; финал только для команд, прошедших онлайн-отбор 20 сентября 2026 года. Регистрация закрыта (по данным The Tech, она шла до 19 сентября). Даты FAIO 2027 не объявлены, на сайте сказано лишь, что следующая олимпиада пройдёт в 2027 году.', true, array['https://faio.kz/', 'https://faio.kz/final/', 'https://the-tech.kz/registracziya-na-mezhdunarodnuyu-ai-olimpiadu-faio-2026-prodlitsya-do-19-sentyabrya'], 'Хорошая ступень перед AI Olymp и IOAI, и в отличие от AI Olymp здесь нет ограничения по классам. Задачи прошлых лет открыты на GitHub.', false),
  ('kaggle-competitions', 'Соревнования Kaggle', 'competition', 'Kaggle (Google)', array['ai'], 'online', 8, 12, 'По политике конфиденциальности Kaggle детям до 13 лет пользоваться сайтом нельзя; в 13–16 лет — только после подтверждённого согласия родителей. Всем младше 18 лет (возраст совершеннолетия в Казахстане) нужно отдельное согласие родителей на каждое соревнование. В стандартных правилах соревнований (даже учебного Titanic) стоит условие: 18 лет или возраст совершеннолетия, если спонсор не согласовал иное и не получено согласие родителей. Поэтому школьникам доступно в основном обучение, а на призы рассчитывать обычно не приходится.', 'Индивидуально или командой; размер команды задают правила конкретного соревнования', 'Бесплатно', 'Крупнейшая платформа соревнований по машинному обучению: учебные и призовые конкурсы, датасеты, бесплатные ноутбуки с GPU. Для школьников действуют строгие возрастные правила и нужно согласие родителей.', 'На Kaggle постоянно идут соревнования разного уровня: учебные бессрочные Getting Started (Titanic, House Prices, Digit Recognizer), учебные Playground и крупные призовые конкурсы от компаний и исследовательских лабораторий. Участники отправляют предсказания своих моделей и видят своё место в публичном рейтинге; за высокие места дают медали и звания Kaggle, которые ценятся в индустрии. Там же бесплатно доступны ноутбуки с GPU, тысячи датасетов и открытые решения других участников. По практике это лучший тренажёр перед ML-олимпиадами: задачи с данными и метрикой качества похожи на практические туры IOAI, AI Olymp и FAIO. Начать стоит с Titanic и курсов Kaggle Learn, потом переходить к Playground.', 'Зарегистрироваться на kaggle.com (с 13 лет). Ученикам 13–16 лет нужно до начала работы оформить согласие родителей, а всем младше 18 — согласие на каждое соревнование (порядок уточняется через Kaggle Support). Перед участием прочитать раздел Rules → Eligibility нужного соревнования.', 'https://www.kaggle.com/competitions', null, null, null, null, 'Соревнования идут круглый год, у каждого свои сроки; учебные Getting Started бессрочные. Общих дат цикла нет.', false, array['https://www.kaggle.com/privacy', 'https://www.kaggle.com/terms', 'https://www.kaggle.com/competitions/titanic/rules'], 'Правила отдельных соревнований могут ограничивать страны и возраст, их нужно проверять каждый раз. Регистрацию младшего школьника лучше проводить вместе с родителем.', false),
  ('kaggle-learn', 'Kaggle Learn — бесплатные микрокурсы по Python и машинному обучению', 'course', 'Kaggle (Google)', array['ai'], 'online', 8, 12, 'Нужен аккаунт Kaggle: с 13 лет, в 13–16 лет — только после подтверждённого согласия родителей.', 'Индивидуально', 'Бесплатно, сертификаты тоже бесплатные', 'Короткие практические курсы прямо в браузере: Python, Pandas, машинное обучение, глубокое обучение, компьютерное зрение и другие, с бесплатными сертификатами.', 'Kaggle Learn — это 17 коротких курсов: Intro to Programming, Python, Pandas, Intro to Machine Learning, Intermediate Machine Learning, Feature Engineering, Data Visualization, Data Cleaning, Intro to Deep Learning, Computer Vision, Time Series, SQL, Intro to AI Ethics, Machine Learning Explainability, Intro to Game AI and Reinforcement Learning и другие. Каждый курс состоит из нескольких уроков с упражнениями в ноутбуках Kaggle, ничего устанавливать не нужно. За прохождение курса выдают бесплатный сертификат. Курсы на английском языке. Это самый быстрый способ подготовиться к первому соревнованию Kaggle и к онлайн-отбору AI Olymp, где проверяют классическое ML.', 'Зарегистрироваться на kaggle.com и открыть раздел Learn; курсы можно проходить в любом порядке.', 'https://www.kaggle.com/learn', null, null, null, null, 'Курсы доступны в любое время, без сроков.', false, array['https://www.kaggle.com/learn', 'https://www.kaggle.com/privacy'], 'Хорошо дополняет CS50 AI: в CS50 больше теории, в Kaggle Learn — практика с pandas и scikit-learn.', false),
  ('zindi', 'Соревнования Zindi', 'competition', 'Zindi (платформа соревнований по data science и ИИ)', array['ai'], 'online', null, 12, 'По условиям использования Zindi пользователю должно быть не меньше 18 лет, иначе его должен представлять родитель или законный опекун. Соревнования открыты для участников со всего мира, но в правилах отдельных конкурсов бывают географические ограничения на попадание в рейтинг и призы (многие задачи ориентированы на Африку), поэтому раздел Rules нужно читать для каждого соревнования.', 'Индивидуально или командой до 4 человек; несколько аккаунтов на одного человека запрещены', 'Бесплатно', 'Платформа ML-соревнований с прикладными задачами, в основном из Африки; на ней проходил практический тур IAIO 2026. Школьники участвуют только при представительстве родителя.', 'Zindi — крупная сеть специалистов по данным и разработчиков ИИ: компании, НКО и исследовательские проекты публикуют задачи с данными, а участники соревнуются в качестве моделей на рейтинге. Темы прикладные: сельское хозяйство, здравоохранение, климат, финансы, распознавание речи и обработка языков с малым количеством данных. Призовые соревнования идут вместе с учебными, на сайте есть бесплатные курсы и разборы решений победителей. Платформу используют и олимпиады: практический тур IAIO 2026 проходил на Zindi. Готовиться так же, как к Kaggle: Python, pandas, scikit-learn, затем нейросети.', 'Зарегистрироваться на zindi.africa (ученикам младше 18 лет — с участием родителя), выбрать соревнование и внимательно прочитать его правила об участниках и призах.', 'https://zindi.africa/competitions', null, null, null, null, 'Соревнования запускаются круглый год, у каждого свои сроки; общих дат нет.', false, array['https://zindi.africa/terms', 'https://zindi.africa/rules', 'https://zindi.africa/learn', 'https://ircai.org/iaio-2026-successfully-concluded-ircai-supports-the-next-generation-of-responsible-ai-professionals/'], 'Несовершеннолетним формально нужно представительство родителя, поэтому аккаунт лучше заводить вместе с ним. Перед стартом проверить, не закрыты ли призы для жителей Казахстана.', false),
  ('technovation', 'Technovation Challenge 2026–2027 (Technovation Girls и смешанный трек)', 'competition', 'Technovation (США); в Казахстане — ОФ «Kinergy» (Technovation Kazakhstan) при поддержке Yandex Qazaqstan', array['ai', 'startup'], 'online', 7, 12, 'Участники 8–18 лет. Дивизион определяется по возрасту старшего участника на 1 августа 2027: Beginner 8–12, Junior 13–15, Senior 16–18. Трек назначается автоматически по составу команды: Girls (команды девочек) или впервые в сезоне 2026–27 — Co-ed (смешанные команды).', '1–5 участников; рекомендуется взрослый ментор (регистрируется на платформе отдельно).', 'Бесплатно', 'Международная программа-конкурс: за сезон команда школьников создаёт работающее цифровое решение с кодом и/или ИИ для реальной проблемы своего сообщества; с 2026–27 к треку для девочек добавился смешанный трек.', 'Команды учатся по бесплатной программе (Scratch, MIT App Inventor, Thunkable; можно Python, Swift, Java и др.) и делают работающий проект: мобильное или веб-приложение, чат-бот или ИИ-ассистента, дашборд данных, ИИ-агента, робота или гаджет. В заявку входят одно видео до 4 минут, код или ссылка на работающий проект и письменные разделы на английском; у дивизиона Senior — бизнес-канвас, у Junior — план привлечения пользователей. Судейство: четвертьфинал на региональных питч-ивентах и онлайн, затем онлайн-полуфинал; в треке Girls выбирают 15 финалистов и вручают гран-при по дивизионам на World Summit, формат наград Co-ed трека определят после закрытия подачи. В Казахстане программу с 2016 года ведёт ОФ «Kinergy»: в сезоне 2026 было около 2 200 заявок и 231 команда, итоговые мероприятия прошли в Алматы и Астане, а в 2024 году казахстанская команда получила технический приз на Global Summit. Для клуба это естественный проект для трека AI с бизнес-частью для трека startup.', 'Зарегистрировать участников и ментора на technovationchallenge.org (регистрация с 11–12 октября 2026 до 11 марта 2027, 23:59 UTC), собрать команду на платформе и подать проект до 5 мая 2027, 17:00 PDT. Казахстанское отделение: technovation.kz, technovationkz@gmail.com, Telegram t.me/TechnovationKz2.', 'https://technovationchallenge.org/competition/', 'https://technovationchallenge.org/get-involved/students/', date '2027-03-11', date '2026-10-12', null, 'Подтверждено официальными страницами сезона 2026–27: сезон стартует 12 октября 2026 (в списке ключевых дат открытие регистрации — 11 октября); регистрация до 11 марта 2027, 23:59 UTC (в одном месте опечатка «2026»); подача проектов — до 5 мая 2027, 17:00 PDT (= 05:00 6 мая по времени Казахстана); четвертьфинал — 11 мая – 7 июня 2027; полуфиналисты — 14 июня; полуфинал — 15–28 июня; финалисты — июль 2027; дата и место World Summit не объявлены. Сроки казахстанского отделения на 2026–27 не опубликованы.', true, array['https://technovationchallenge.org/competition/', 'https://technovationchallenge.org/submission-guidelines/', 'https://technovationchallenge.org/get-involved/students/', 'https://technovation.kz/', 'https://the-tech.kz/yandex-qazaqstan-nagradil-luchshie-it-proekty-shkolnicz-kazahstana-na-regionalnom-finale-technovation-girls/', 'https://digitalbusiness.kz/2025-12-09/technovation-girls-kazakhstan-otkrila-nabor-mentorov-dlya-novogo-sezona/', 'https://technovationchallenge.org/program-timeline', 'https://technovationchallenge.org/get-involved/students', 'https://technovationchallenge.org/'], 'Срок в карточке — окончание регистрации; проект нужно подать до 5 мая 2027. Письменные материалы — только на английском; видео можно на любом языке с английскими субтитрами. Сайт technovation.kz не обновлён (там сроки 2025 года) — актуальное уточнять у ОФ «Kinergy».', false),
  ('waicy-2026', 'WAICY 2026 — World Artificial Intelligence Competition for Youth', 'competition', 'WAICY (ReadyAI / WholeRen Education, Питтсбург, США); региональные этапы проводят организаторы в отдельных странах', array['ai'], 'online', 7, 12, 'Школьники 6–18 лет со всего мира, можно участвовать удалённо; Казахстан есть в списке стран. При подаче выбирается группа: Elementary, Middle или High School.', 'Индивидуально или командой; от команды подаётся одна заявка, жёсткого лимита на размер нет (организаторы раньше рекомендовали 3–5 человек)', 'На официальных страницах плата не указана; сторонние обзоры называют участие бесплатным, лучше уточнить в Guidebook 2026', 'Международный онлайн-конкурс ИИ-проектов для школьников 6–18 лет: ИИ-решение реальной проблемы, ИИ-арт, ИИ-видео или настройка языковой модели под роль эксперта.', 'В 2026 году в конкурсе четыре трека: AI Showcase (проект с ИИ, решающий реальную задачу), AI Generated Art, AI Generated Video и AI Large Language Model (нужно настроить LLM на роль эксперта в определённой области). Проект загружают в открытую папку Google Drive через онлайн-форму, описание — не больше 200 слов. На финальном этапе 4–6 декабря участники онлайн защищают работы в назначенное время, победителей объявят 7 декабря. Имена участников печатаются на сертификатах и наградах. Это конкурс проектов, а не олимпиада: уровень ниже IOAI, зато подходит для первых публичных ИИ-проектов. Для клуба лучше всего подходит трек AI Showcase: небольшой проект на Python (классификатор, чат-бот, компьютерное зрение) с понятной пользой.', 'Подать проект через форму на waicy.org/2026-submission до 29 ноября 2026 года, 17:00 по восточному времени США (30 ноября, 03:00 по Астане).', 'https://waicy.org/waicy-2026/', 'https://www.waicy.org/2026-submission/', date '2026-11-29', date '2026-12-04', date '2026-12-06', 'По официальной странице WAICY 2026: приём проектов с 1 октября, дедлайн — 29 ноября 2026 года в 17:00 ET, 2 декабря участникам назначают время выступления, финал онлайн 4–6 декабря 2026 года, итоги — 7 декабря.', true, array['https://waicy.org/waicy-2026/', 'https://waicy.org/', 'https://www.waicy.org/2026-submission/'], 'Сроки короткие: на проект осталось около семи недель. Хороший вариант для 7–9 классов.', false),
  ('cs50-ai', 'CS50''s Introduction to Artificial Intelligence with Python (CS50 AI)', 'course', 'Гарвардский университет (CS50)', array['ai'], 'online', 7, 12, 'Открыт для всех и бесплатен. По FAQ курсы CS50 лучше всего подходят учащимся от 12 лет, младшим может понадобиться помощь родителей. Перед курсом рекомендуется пройти CS50x или иметь около года опыта на Python. Для сдачи проектов нужен аккаунт GitHub, для обратной связи — аккаунт edX; у этих сервисов могут быть свои возрастные ограничения.', 'Индивидуально', 'Бесплатно, включая сертификат CS50; верифицированный сертификат edX платный', 'Семинедельный курс Гарварда по основам ИИ на Python: поиск, логика, вероятности, оптимизация, машинное обучение, нейросети и языковые модели, с бесплатным сертификатом.', 'Курс состоит из 7 недель: поиск, знания и логика, неопределённость, оптимизация, машинное обучение, нейронные сети и обработка языка, включая большие языковые модели. На каждую неделю есть лекция и практические проекты на Python: игровые ИИ, распознавание рукописных символов, машинный перевод и др. Проекты проверяет автоматическая система CS50; для бесплатного сертификата нужно сдать все проекты минимум на 70%. Работать можно в своём темпе, промежуточных дедлайнов нет. Это основной курс трека ИИ в AIT Club и хорошая база для AI Olymp и IOAI: теория вместе с практикой на Python.', 'Открыть cs50.harvard.edu/ai, смотреть лекции и сдавать проекты через GitHub; для обратной связи завести аккаунт edX. Ссылка на сертификат появится в Gradebook примерно через 4 часа после зачёта последнего проекта.', 'https://cs50.harvard.edu/ai/', null, date '2027-06-30', null, null, 'По FAQ курса текущий срок — до 30 июня 2027 года, 23:59 UTC. За несколько месяцев до него команда CS50 может продлить курс на 6 или 12 месяцев; тогда проекты, зачтённые в текущем сроке (начался 1 января 2026 года), переносятся. Промежуточных дедлайнов нет.', true, array['https://cs50.harvard.edu/ai/', 'https://cs50.harvard.edu/ai/certificate/', 'https://cs50.harvard.edu/ai/faqs/'], 'Курс на английском. Имя в сертификате потом изменить нельзя, вводить его нужно внимательно.', false),
  ('elements-of-ai', 'Elements of AI (Introduction to AI и Building AI)', 'course', 'Хельсинкский университет и MinnaLearn', array['ai'], 'online', 7, 12, 'Открыт для всех. Для Introduction to AI не нужны ни сложная математика, ни программирование, для Building AI желателен базовый Python. Возрастных ограничений на сайте нет. Русской и казахской версий нет: можно проходить глобальную англоязычную или, например, украинскую версию.', 'Индивидуально', 'Курсы бесплатные. Сертификат Introduction to AI бесплатный, электронный сертификат Building AI стоит 50 евро.', 'Популярный вводный курс по ИИ от Хельсинкского университета: что такое ИИ, как работают машинное обучение и нейросети и как ИИ влияет на общество, без сложной математики.', 'Introduction to AI состоит из 6 глав: что такое ИИ, решение задач с помощью ИИ, ИИ в реальном мире, машинное обучение, нейронные сети и последствия ИИ. На каждую часть уходит примерно 4–8 часов, пройти весь курс рекомендуют за 6 недель. Для бесплатного сертификата нужно выполнить не меньше 90% упражнений и правильно решить не меньше 50%; часть ответов проверяется взаимно, поэтому нужно оценить минимум 3 работы других участников. Продолжение — Building AI (около 50 часов): алгоритмы ИИ, упражнения трёх уровней сложности, на средних и продвинутых нужно программировать на Python. Курс хорошо подходит ученикам 7–9 классов как первый шаг перед CS50 AI.', 'Бесплатно зарегистрироваться на course.elementsofai.com и выбрать язык курса; сертификат появится в профиле после проверки ответов.', 'https://www.elementsofai.com/', 'https://course.elementsofai.com/', null, null, null, 'Курс доступен в любое время, проходится в своём темпе, сроков нет.', false, array['https://www.elementsofai.com/', 'https://course.elementsofai.com/', 'https://www.elementsofai.com/faq/what-are-the-requirements-for-completing-the-introduction-to-ai-and-building-ai-courses-2', 'https://www.elementsofai.com/faq/i-have-passed-an-elements-of-ai-course-where-is-my-certificate-2', 'https://www.elementsofai.com/faq/how-many-hours-will-the-course-take', 'https://www.elementsofai.com/faq/terms-and-conditions'], 'Сертификат выдаётся на том языке, на котором пройден курс; при смене языка прогресс по упражнениям сбрасывается. Проверка взаимных оценок может затянуться, поэтому не стоит обещать сертификат к конкретной дате.', false),
  ('republican-school-hackathon', 'Республиканский хакатон для школьников (Astana Daryn × CAP Education × Astana Hub)', 'hackathon', 'Центр «Astana Daryn» и онлайн-школа программирования CAP Education; главный партнёр — Astana Hub, партнёры — Astana IT University, TrustExam, JUZ40 Education', array['ai', 'startup'], 'kz', null, null, 'Школьники Казахстана из любых регионов (в 2026 году отбор проходили ученики со всей страны); требования к классу на странице не указаны.', 'Командный формат; размер команды на странице не указан.', 'Взнос на странице не упоминается.', 'Республиканский хакатон для школьников с треками Digital Business & GovTech, AI & Big Data и Smart Technologies & IoT: онлайн-отбор, неделя на MVP и финальная защита перед жюри и инвесторами.', 'В 2026 году отборочный этап прошёл онлайн в формате теста на платформе прокторинга TrustExam: зарегистрировались более 1 000 школьников из 300+ команд и 100+ школ, дальше прошли 75 команд. На втором этапе команды неделю разрабатывали MVP, а в финале 50 команд в трёх треках (25 — Digital Business & GovTech, 19 — AI & Big Data, 6 — Smart Technologies & IoT) защищали проекты перед экспертами, жюри и инвесторами. Призы — 1–3 места в каждом треке и спецноминации, инвестиционные сертификаты на реализацию стартапа (за 1-е место 150 000 + 50 000 тенге, за 2-е — 75 000 + 25 000, за 3-е — 50 000 + 20 000 тенге), а около 30 призёров получили бесплатный доступ к программам Astana Hub Startup School и Startup Academy. В карточке события указан адрес Astana IT University (EXPO, Астана). Хорошая тренировка быстрого MVP и питча для треков startup и AI.', 'Следить за анонсами в разделе событий astanahub.com и у центра Astana Daryn; в 2026 году для подтверждения участия требовалось зарегистрироваться на astanahub.com и установить приложение Astana Hub.', 'https://astanahub.com/en/event/respublikanskii-khakaton-dlia-shkolnikov1770973516/', null, null, null, null, 'Даты следующего хакатона не объявлены. В 2026: отборочный этап — 10 января, второй этап (разработка MVP) — 12–17 января; в карточке события указаны даты 14–15 февраля 2026 (по-видимому, финал).', false, array['https://astanahub.com/en/event/respublikanskii-khakaton-dlia-shkolnikov1770973516/'], 'Формат финала уточнять: в карточке события стоит пометка «Online» и одновременно адрес в Астане; если финал очный, команде из Петропавловска понадобится поездка (о компенсации не сказано). Отборочный этап — онлайн-тест с прокторингом, к нему стоит готовиться отдельно.', false),
  ('itfest-hackathon', 'Хакатон ITFest (категория Digital School)', 'hackathon', 'Альянс вузов IITU, KBTU, Astana IT University и UIB совместно с программой AI Talents Almaty при поддержке общественного фонда NNEF', array['ai', 'startup'], 'kz', 10, 11, 'По положению 2025 года категория Digital School — для учеников 10–11 классов (на главной странице сайта — «школьники и студенты колледжей»). Для студентов вузов есть отдельная категория Digital University.', 'Команда; на главной странице фестиваля — не больше 3 человек', 'В положении 2025 года не указана', '24-часовой офлайн-хакатон на крупном молодёжном IT-фестивале в Алматы, где каждый проект обязан содержать ИИ-компонент; для школьников есть отдельная категория.', 'ITFest — ежегодный фестиваль цифровых и креативных индустрий в Алматы; в 2025 году он прошёл 5–6 декабря в выставочном центре «Атакент». Хакатон 2025 года шёл по трём трекам: ИИ и облачные инструменты для образования; данные, ИИ и облака для прогнозирования, безопасности и бизнеса; диалоговые системы (чат-боты, голосовые и мультимодальные ассистенты). Задачи от партнёров публиковали в день старта, на разработку давалось ровно 24 часа; по ходу были контрольные точки (Git-репозиторий, презентация, прототип), а в конце — очный питч. Призы в категории Digital School в 2025 году — 250 000, 200 000 и 150 000 ₸ и скидки на обучение в вузах-организаторах (на главной странице и в положении условия расходились). Для подготовки стоит заранее потренироваться подключать готовые ИИ-API и быстро делать интерфейс, а также распределить роли в команде.', 'Следить за сайтом itfest.kz и Telegram-каналом t.me/itfest_official. В 2025 году регистрация шла через форму на itfest.kz до дня старта.', 'https://itfest.kz/hackathon/', null, null, null, null, 'Даты ITFest 2026 не объявлены: на 10 октября 2026 на сайте выложены материалы 2025 года. Предыдущий выпуск прошёл 5–6 декабря 2025 года в Алматы, регистрация шла до 5 декабря 2025 года.', false, array['https://itfest.kz/hackathon/', 'https://itfest.kz/'], 'Хакатон проходит офлайн в Алматы, участникам из Петропавловска нужна поездка. Скидки на обучение по положению 2025 года давались при среднем балле не ниже 70.', false),
  ('nasa-space-apps-petropavlovsk', 'NASA Space Apps Challenge 2026 — Петропавловск', 'hackathon', 'NASA; локальная площадка — American Corner и Makerspace Петропавловск', array['ai', 'startup'], 'sko', null, null, 'Открыт для всех возрастов. Участника до 18 лет регистрирует родитель или законный представитель, и он должен сопровождать ребёнка всё время мероприятия; локальная площадка может ставить дополнительные условия. В Петропавловске после анкеты проводится собеседование (мотивация, навыки, командная динамика).', 'До 6 человек; все участники команды должны быть зарегистрированы на одну и ту же локальную площадку. Можно участвовать и одному, но организаторы рекомендуют команду.', 'Бесплатно', 'Глобальный двухдневный хакатон NASA по открытым космическим и земным данным; 14–15 ноября 2026 года проходит очно в Петропавловске, в областной научной библиотеке им. Сабита Муканова.', 'Команды выбирают одну из 14 задач, подготовленных экспертами NASA и партнёрских космических агентств (тема 2026 года — «The Next Frontier»); краткие описания опубликованы 17 сентября, полные условия выходят 28 октября, начинать работу над задачей до хакатона запрещено. За два дня команда делает прототип — приложение, визуализацию, модель или инструмент на данных NASA — и сдаёт проект через страницу команды до окончания локального события. Все сдавшие проект получают сертификат, лучшие проходят глобальное судейство: номинанты и финалисты объявляются в декабре 2026, глобальные победители — в январе 2027. Площадку в Петропавловске (организаторы называют её второй ежегодной) проводят American Corner и Makerspace: лимит 50 участников, в программе открытие и формирование команд, работа с менторами, финальная разработка, защита перед жюри и награждение. В 2026 году локальные площадки в Казахстане есть также в Алматы, Астане, Павлодаре, Уральске и Шымкенте. Для подготовки стоит заранее собрать команду с ролями (данные и ML, фронтенд, питч) и разобрать условия задач после 28 октября.', 'Создать аккаунт на spaceappschallenge.org и зарегистрироваться на хакатон 2026 (за несовершеннолетнего — родитель), выбрать локальное событие Petropavlovsk; заполнить анкету площадки до 1 ноября 2026 и вступить в Telegram-чат по ссылкам на странице события; пройти собеседование и оформить команду на сайте.', 'https://www.spaceappschallenge.org/2026/local-events/petropavlovsk/', 'https://forms.gle/rcAqozpGv1eWmdgB8', date '2026-11-01', date '2026-11-14', date '2026-11-15', 'Подтверждено: глобальный хакатон — 14–15 ноября 2026 (официальный FAQ; регистрация на сайте открыта с 26 августа до конца хакатона 15 ноября, полные условия задач — 28 октября). Страница площадки в Петропавловске: 14–15 ноября 2026, анкета — до 1 ноября 2026. В расписании на той же странице остались, по-видимому, фрагменты прошлогоднего шаблона («14–15 октября», «приезд в Алматы 4–5 октября») — уточнить у организатора.', true, array['https://www.spaceappschallenge.org/2026/local-events/petropavlovsk/', 'https://www.spaceappschallenge.org/resources/participant-faqs/', 'https://digitalbusiness.kz/2024-10-02/nasa-provedet-hakatoni-srazu-v-pyati-gorodah-kazahstana/'], 'Площадка: областная универсальная научная библиотека им. Сабита Муканова, ул. Конституции Казахстана, 25 (очный формат). Контакт локального лида: svyatoslav.lengard@kz.americanspaces.info, Instagram american_corner_petropavlovsk. Правила для участников до 18 лет: нельзя ставить своё фото на аватар и страницу команды и использовать лица и голоса несовершеннолетних в демо-видео проекта — учесть правила клуба о данных детей. В 2024 году казахстанские площадки (включая Петропавловск) принимали участников с 14 лет.', false),
  ('conrad-challenge', 'Conrad Challenge 2026–2027', 'startup', 'Conrad Challenge, Space Center Houston (США); генеральный партнёр — Equinor', array['startup', 'ai'], 'intl', 7, 12, 'Учащиеся 13–18 лет из любой страны (критерий — возраст, а не класс). Можно объединяться с учениками других школ, городов и стран; участники прошлых лет допускаются повторно.', '2–5 учащихся + тренер (coach) старше 18 лет: учитель, родитель или профильный эксперт.', 'Этап Activation (регистрация и Lean Canvas) бесплатный; при подаче Innovation Stage — взнос $499 с команды, доступна финансовая помощь по заявке (приём заявок на помощь — 2 ноября – 3 декабря 2026).', 'Международный конкурс инноваций и бизнес-планов для команд 13–18 лет: от Lean Canvas к инновационному брифу, видео и сайту, финал — Innovation Summit в Space Center Houston.', 'Этап 1 (Activation): команда с тренером регистрируется в портале Award Force, выбирает категорию и отвечает на 12 вопросов Lean Canvas; заявки рассматриваются по мере поступления, поэтому подавать лучше раньше. Категории сезона: Aerospace and Aviation, Cyber-Technology and Security, Energy and Environment, Health and Nutrition и The Water Challenge. Этап 2 (Innovation, онлайн): инновационный бриф до 3 000 слов (питч, команда, проблема, технология, валидация, рынок, конкуренты, выход на рынок, бизнес-модель, финансирование), видео 3–5 минут с моделью или прототипом и сайт команды; судьи дают письменный фидбэк, в феврале 2027 объявляют Conrad Innovators и финалистов. Оценка: инновационность 30%, сторителлинг 20%, реализуемость 20%, маркетинг 20%, финансы 10%. Этап 3: финалисты едут на Innovation Summit в Хьюстон (питчи, выставка, экскурсии NASA) и соревнуются за стипендии и звание Pete Conrad Scholar. Подготовка совпадает с треком startup: Lean Canvas, интервью с клиентами, MVP или прототип, питч на английском.', 'Собрать команду и тренера, зарегистрировать всех в портале Conrad Challenge Award Force через conrad.spacecenter.org (участники и их законные представители знакомятся с правилами) и подать Lean Canvas до 29 октября 2026; затем до 7 января 2027 загрузить бриф, видео, ссылку на сайт и оплатить взнос.', 'https://conrad.spacecenter.org/', null, date '2026-10-29', date '2027-04-21', date '2027-04-24', 'Подтверждено официальным Student Guide 2026–2027: Activation — 27 августа – 29 октября 2026, 23:59 CT (≈ 09:59 30 октября по времени Казахстана); Innovation Stage — до 7 января 2027, 23:59 CT (≈ 10:59 8 января по времени Казахстана); финалисты — февраль 2027; Innovation Summit — 21–24 апреля 2027, Хьюстон. На главной странице сайта местами указаны 30 октября и 8 января — ориентироваться на более ранние даты.', true, array['https://conrad.spacecenter.org/wp-content/uploads/2026/08/2026-2027-Conrad-Challenge-Student-Guide-Official.pdf', 'https://conrad.spacecenter.org/'], 'Всё на английском. Финал очный в США: финалистам понадобятся визы и бюджет на поездку. Прямая ссылка на портал Award Force в просмотренных материалах не найдена — вход через сайт конкурса.', false),
  ('diamond-challenge', 'Diamond Challenge 2026–2027', 'startup', 'Horn Entrepreneurship, Университет Делавэра (США)', array['startup'], 'intl', 8, 12, 'Старшеклассники 14–18 лет на дату дедлайна подачи, из любой страны. Один ученик — одна команда и один проект в сезон; выручка проекта до дедлайна — не более $100 000; проекты, уже выходившие в финал, повторно не принимаются.', '2–4 ученика + один взрослый наставник (advisor) 21+.', 'Взнос в официальных правилах не предусмотрен; сторонние обзоры называют участие бесплатным.', 'Международный конкурс бизнес- и социальных стартапов для старшеклассников от Университета Делавэра с призами более $100 000; финал — Limitless World Summit в США.', 'При подаче команда выбирает трек (Business Innovation или Social Innovation) и формат питч-раунда — живой питч у партнёра-организатора или виртуальный. Первый раунд — письменный нарратив на 3–5 страниц на английском (проблема, клиенты, решение, отличие от альтернатив, экономика, команда, подтверждения спроса) и видео-знакомство до 60 секунд. Набравшие минимальный балл выходят в питч-раунд: 5 минут питча (дека до 15 слайдов) и 3 минуты вопросов жюри, вживую или записанным видео. Лучшие команды приглашаются на Limitless World Summit, где очно должен присутствовать хотя бы один участник (при отказе в визе возможна отсрочка на год). Призы в каждом треке — $12 000, $8 000 и $4 500, плюс тематические призы (в т. ч. Horn Entrepreneurship Global Prize); ежемесячно проходят обучающие вебинары Spark Sessions. В 2025 году команда НИШ Тараз первой из Казахстана вышла в финал с устройством ASAR для людей с инвалидностью.', 'Подать заявку через diamondchallenge.org (платформа diamondchallenge.secure-platform.com): выбрать трек и формат питча, загрузить нарратив в PDF и публичную ссылку на 60-секундное видео до 14 января 2027, 17:00 EST.', 'https://diamondchallenge.org/', 'https://diamondchallenge.secure-platform.com', date '2027-01-14', date '2027-04-29', date '2027-04-30', 'По официальной странице дат Horn Entrepreneurship (сезон 2026–27; «даты могут измениться»): приём открыт с 16 сентября 2026; дедлайн — 14 января 2027, 17:00 EST (= 03:00 15 января по времени Казахстана); судейство — 22 января – 3 февраля; приглашения в питч-раунд — 10 февраля; видео-питчи виртуальных участников — до 16 февраля; живые питч-ивенты — 16 февраля – 7 марта; финалисты виртуального трека — 9 марта; Limitless World Summit — 29–30 апреля 2027. Год на странице прямо не подписан, но она относится к сезону 26–27, и дни недели совпадают с 2027 годом.', true, array['https://horn.udel.edu/deadlines2627', 'https://horn.udel.edu/hubfs/2027%20Diamond%20Challenge/26-27%20Diamond%20Challenge%20Rules.pdf', 'https://diamondchallenge.org/', 'https://schools.nis.edu.kz/en/school/nzm-taraz/news/1154', 'https://jaworldwide.org/locations'], 'Все материалы на английском; называть свою школу в материалах нельзя. Живых питч-ивентов в Казахстане в найденных источниках нет — реалистичный путь для команды из Петропавловска — виртуальный питч. Финал очный в США (в 2025 году — Уилмингтон, Делавэр). Для справки: программы Junior Achievement Kazakhstan (в т. ч. Company Program) подтвердить не удалось — JA Kazakhstan нет в актуальном списке стран сети JA Worldwide, свежих новостей и рабочего сайта не найдено, поэтому отдельной карточки нет; Diamond Challenge и Blue Ocean — ближайшие доступные аналоги.', false),
  ('earth-prize', 'The Earth Prize 2027', 'competition', 'The Earth Foundation', array['startup'], 'online', 6, 12, 'Учащиеся, родившиеся в 2007–2014 годах и обучающиеся в школе, на домашнем обучении или в другой образовательной программе; конкурс открыт для подростков всего мира. Для несовершеннолетних обязательно согласие родителя или опекуна.', 'Индивидуально или команда до 5 учеников из любых классов и школ; капитан подаёт одну работу за всю команду.', 'Бесплатно для учеников и школ.', 'Крупнейший международный конкурс экологических решений для подростков 13–19 лет с призовым фондом $104 500: команда доказывает реальность экологической проблемы, тестирует прототип и питчит решение.', 'Участники регистрируются, получают доступ к сообществу Earth Foundation в Discord с менторами-волонтёрами и готовят Earth Prize Blueprint — пошаговый шаблон из семи блоков от проверки проблемы до видеопитча. Работы оценивают по шести критериям (всего 25 баллов): валидация проблемы, proof of concept, качество решения, следующие шаги, реализуемость и финплан, коммуникация. 35 команд становятся Earth Prize Scholars и месяц дорабатывают проект с персональным ментором (обновление проекта, бюджет, видео, лист по интеллектуальной собственности). Из них жюри выбирает семь региональных победителей, каждый получает USD 10 000 на реализацию проекта, а глобального победителя определяет публичное голосование. Принимаются любые экологические решения: климат, загрязнение, биоразнообразие, отходы, вода, энергия, устойчивые материалы. Критерии почти совпадают с треком startup: интервью с затронутыми людьми, прототип и тест с пользователями, финансовый план, питч.', 'Каждый участник регистрируется на theearthprize.org до 10 января 2027 (для несовершеннолетних — с данными родителя для согласия); капитан создаёт команду в Submissions Portal и приглашает участников; Blueprint подаётся до 31 января 2027.', 'https://www.theearthprize.org/competition', 'https://www.theearthprize.org/2027', date '2027-01-10', date '2027-05-28', date '2027-05-28', 'Подтверждено официальным сайтом (The Earth Prize 2027): регистрация — с 11 января 2026 до 10 января 2027; приём работ — до 31 января 2027; отбор Scholars — 1–25 февраля, объявление — 3 марта; этап Scholars — 3–31 марта; региональные победители — 3–9 мая; публичное голосование — 10–23 мая; церемония награждения — 28 мая 2027.', true, array['https://www.theearthprize.org/competition', 'https://www.theearthprize.org/2027', 'https://www.theearthprize.org/faq'], 'Срок в карточке — окончание регистрации; работу нужно подать до 31 января 2027. Язык подачи на просмотренных страницах не указан — готовить материалы на английском. Менторинг идёт в Discord — для несовершеннолетних согласовать использование платформы с родителями.', false),
  ('blue-ocean', 'Blue Ocean Student Entrepreneur Competition 2027', 'startup', 'Blue Ocean Competition (методология «Стратегия голубого океана»)', array['startup'], 'online', 9, 12, 'Ученики старшей школы любой страны или эквивалентного доуниверситетского уровня (A-Level, IB); на домашнем обучении — 14–18 лет. Нужно быть учащимся на момент регистрации.', 'Индивидуально или команда до 5 учеников, можно из разных школ; одна заявка на команду.', 'Бесплатно (регистрация, мини-курс и подача).', 'Полностью онлайн-конкурс видеопитчей для старшеклассников со всего мира: нужно предложить бизнес-идею, создающую «голубой океан» — новый рынок без прямой конкуренции.', 'Участники проходят бесплатный мини-курс и записывают видеопитч до 5 минут на английском, обязательно используя инструменты Blue Ocean: Strategy Canvas, три уровня неклиентов и сетку «Устранить–Снизить–Повысить–Создать». Питчи оценивают предприниматели и бизнес-эксперты по пяти равным критериям: ценностная инновация, рыночный потенциал, коммерческая жизнеспособность и масштабируемость, техническая реализуемость, качество презентации и применение инструментов. Призы: 1-е место — $1 000, 2-е — $750, 3-е — $500, приз зрительских симпатий — $750 (среди Top 100), по $500 региональным победителям (включая регион «Азия и Океания») и награды учителям-кураторам. Все приславшие работу получают сертификат участника, Top 10 — сертификат за выдающиеся достижения. Конкурс не требует поездок и денег, поэтому подходит как первый международный опыт для трека startup.', 'Зарегистрироваться на blueoceancompetition.org/register, пройти мини-курс, загрузить видео на YouTube с хештегом #blueoceancompetition и отправить ссылку и файл через blueoceancompetition.org/submit до 21 февраля 2027 (полночь по местному времени).', 'https://blueoceancompetition.org/', 'https://blueoceancompetition.org/register/', date '2027-02-21', date '2027-05-13', date '2027-05-13', 'Подтверждено на официальном сайте (сезон 2027): регистрация в любое время до дедлайна; подача — до 21 февраля 2027, полночь по часовому поясу участника; Top 500 и Top 100 — 5 апреля 2027; Top 30 — 22 апреля; Top 10 — 4 мая; онлайн-финал с объявлением победителей — 13 мая 2027.', true, array['https://blueoceancompetition.org/compete/', 'https://www.blueoceancompetition.org/'], 'Видео должно быть оригинальным, на английском и без ускорения; в правилах — «до 5 минут», в FAQ — «3–5 минут», поэтому лучше уложиться в 3–5 минут. Видео публикуется на YouTube — для несовершеннолетних участников заранее согласовать это с родителями.', false),
  ('samsung-solve-for-tomorrow', 'Samsung Solve for Tomorrow Казахстан', 'startup', 'ТОО «Samsung Electronics Central Eurasia»', array['startup', 'ai'], 'kz', 7, 12, 'Школьники 13–18 лет — граждане Казахстана из государственных и частных школ любого региона (критерий — возраст, а не класс). Все участники команды и учитель-наставник должны быть из одной школы и одного города; взрослые в составе команды не допускаются.', 'Команда до 10 школьников из одной школы + обязательный учитель-наставник из той же школы. Финалистам организатор оплачивает проезд и проживание (по FAQ сайта — для 3 участников команды).', 'Бесплатно', 'Республиканский конкурс социальных STEM-проектов и стартапов школьников от Samsung с призовым фондом более 10 млн тенге: команда находит реальную проблему в своём окружении и доводит решение до прототипа.', 'Команда подаёт на сайте презентацию идеи и видео до 2 минут; жюри отбирает около 30 заявок, которые с середины мая до конца июля работают с менторами на семинарах, делают прототип и отправляют финальную презентацию. Десять лучших команд защищают проекты в финале, три победителя получают денежные призы. Тема свободная (медицина, инклюзия, экология, безопасность, образование и т. д.); в 2026 году отдельно выделялись направления «Экологическая устойчивость с помощью технологий» и «Социальные изменения через спорт и технологии». Критерии оценки: креативность и обоснованность данными, ясность и реалистичность решения, учёт местных реалий и целевой аудитории, масштабируемость. В 2026 году заявки подали более 2 800 школьников (858 идей), в финал вышли 11 команд; 1-е место (4 млн тенге) заняла команда MKGA из НИШ Актобе с настольным роботом-аниматроником OquBot, 2-е место — 2,5 млн, 3-е — 1 млн тенге, остальные финалисты получили сертификаты по 300 тыс. тенге на развитие проекта. Для подготовки полезны интервью с пользователями, данные о проблеме и ранний прототип — многие финалисты используют ИИ, IoT и робототехнику.', 'Зарегистрироваться и заполнить анкету на solvefortomorrow.kz: состав команды, учитель-наставник, презентация о команде и идее и видео до 2 минут (в сезоне 2026 — до 30 апреля). Решение об отборе приходит на e-mail.', 'https://solvefortomorrow.kz/ru', 'https://solvefortomorrow.kz/ru', null, null, null, 'Сроки сезона 2027 ещё не объявлены. Конкурс ежегодный (2026 — шестой сезон в Казахстане). В 2026: приём заявок с 1 марта до 30 апреля; отбор до 15 мая; подготовка с менторами — с середины мая до 30 июля; финальные презентации — до 30–31 июля; финалисты объявлены до 5 августа; финал — 25 августа 2026 (прошёл в Астане, в центре alem.ai).', false, array['https://solvefortomorrow.kz/ru', 'https://solvefortomorrow.kz/docs/sft_rules_ru_2026.doc', 'https://news.samsung.com/kz_ru/solve-for-tomorrow-start-2026', 'https://inbusiness.kz/ru/charity/236'], 'Правила 2026 требуют гражданства РК и допускают в команду только учеников одной школы, поэтому участникам AIT Club из разных школ нужно заявляться школьными командами со своим учителем. В правилах местом финала указан Алматы, но финал 2026 прошёл в Астане. В пресс-релизе Samsung о старте сезона опечатка «31 апреля» — по правилам и сайту дедлайн 30 апреля. Организатор собирает ФИО, телефон, e-mail и город участников и может публиковать фото и видео — для несовершеннолетних нужно согласие родителей.', false),
  ('infomatrix-asia', 'Infomatrix-Asia', 'competition', 'Международный фонд «БІЛІМ-ИННОВАЦИЯ» при поддержке Министерства просвещения РК и РНПЦ «Дарын»', array['ai', 'startup', 'algo'], 'kz', 7, 12, 'Команды школьников Казахстана 7–11 (12) классов; иностранные участники — 10–18 лет. Проекты, уже представленные на национальных конкурсах в неизменном виде, не допускаются.', '1–3 участника на проект (кроме Drone Soccer) и один наставник; руководитель может зарегистрировать несколько команд. На финале участник защищает только один проект в одной категории.', 'Платно: по FAQ официального сайта размер взноса зависит от региона и категории и указывается при регистрации.', 'Международный конкурс IT-, научных и стартап-проектов школьников в Астане с категориями AI Programming, AI Hackathon и Startup Pitch; рабочий язык — английский.', 'Конкурс проходит в два этапа: регистрация с онлайн-отбором по документации, видео и другим требованиям секции, затем очный финал в Астане с защитой проекта (5–10 минут) и стендовой презентацией. Категории 2026 года: AI Programming (приложение с алгоритмами и структурами данных, ИИ приветствуется, нужен публичный GitHub), AI Hackathon (онлайн сдаётся CRUDL-проект, ИИ-функции назначаются и встраиваются на месте с ключами OpenAI API), Startup Pitch, Hardware Control, Applied Science, Arduino Hackathon, Computer Art AI, Short Movie и Drone Soccer. В Startup Pitch подаётся питч-дек, приоритет у проектов со стадией MVP, нужен анализ рынка TAM/SAM/SOM; в финале — питч строго 5 минут и 2–5 минут вопросов, оценка по инновационности, реализуемости, рыночному потенциалу и питчу (по 25%). Победители получают дипломы I–III степени (ориентировочно 10/15/20% участников), университеты-партнёры дают гранты лучшим проектам. В 2026 году было более 3 000 заявок, 600 финалистов и свыше 250 команд из 10 стран; девятиклассник НИШ Петропавловска занял 2-е место в категории Hardware Control с умной системой домашнего ухода homepal (детекция падений, голосовой ассистент).', 'Зарегистрироваться на infomatrix.asia (личный кабинет app.infomatrix.asia): ФИО латиницей и кириллицей, ИИН, секция, название проекта, класс, школа, регион, язык обучения, ФИО и e-mail наставника; затем загрузить материалы для онлайн-отбора по требованиям своей секции.', 'https://infomatrix.asia/', 'https://app.infomatrix.asia/login', null, null, null, 'Даты Infomatrix-Asia 2027 ещё не объявлены. Финал 2026 прошёл 25–27 марта 2026 в Астане (Spectrum International School); сроки онлайн-отбора публикуются в официальной документации и в найденных источниках не указаны.', false, array['https://infomatrix.asia/', 'https://docs.google.com/document/d/e/2PACX-1vQwZP6VLBPoFx0ZhbQh228mtYbLgeSKd4bBW0g3ctcWehVFachK00Fu5EhGX4x2CRohNX1AP-XVwOIK/pub', 'https://schools.nis.edu.kz/en/school/nis-petropavl/news/2081'], 'Вся документация и защита — на английском. В AI Programming Telegram-боты и простые интеграции не принимаются, кроме проектов со сложной архитектурой; к финалу нужен работающий MVP. При регистрации собирается ИИН участников — учитывать правила клуба о данных несовершеннолетних. О компенсации проезда до Астаны в правилах не сказано. Контакты: infomatrix@bil.edu.kz, Telegram t.me/infomatrixasia.', false),
  ('tau-innohub-school', 'TAU-InnoHub School — конкурс стартап-проектов школьников', 'startup', 'Университет «Туран-Астана» (Центр предпринимательства и TAU-InnoHub)', array['startup'], 'kz', 8, 12, 'Ученики 10–11 (12) классов общеобразовательных школ; 8–9 классы — по решению оргкомитета. Учителя школ могут выступать наставниками.', 'Индивидуально или командой; ограничение размера команды на странице конкурса не указано.', 'Взнос на официальной странице не упоминается.', 'Республиканский конкурс школьных стартап-проектов в сфере экономики и социальной сферы от Университета «Туран-Астана»: проект на стадии идеи или разработки защищается презентацией до 7 минут.', 'Принимаются оригинальные проекты с элементами новизны и практической ценностью в области экономики и социальной сферы, находящиеся на стадии идеи или разработки. В заявку входят сведения о команде, описание проекта на 1–2 страницах и презентация; на защиту отводится не более 7 минут. Оценивают идею, реализацию, инновационность, команду, социальную значимость, перспективность и устойчивость. Призы — 1–3 места и специальные номинации; оргкомитет может вручать сертификаты на акселерационные программы TAU-InnoHub, а ректор — устанавливать особые условия поступления в университет для победителей и участников. Конкурс проводился в 2025 году и весной 2026 года. Для подготовки достаточно проработанной проблемы, первых интервью с пользователями и понятной модели монетизации — готовый MVP не требуется.', 'Отправить заявку на k.shebeko@tau-edu.kz: ФИО участников на казахском, русском и английском, название и адрес школы, класс, телефон и e-mail, описание проекта (1–2 стр.) и презентацию. Объявления о новом наборе публикуются в разделе Events на tau-edu.kz.', 'https://tau-edu.kz/en/events/otkryt-priyem-zayavok-na-konkurs-startapov', null, null, null, null, 'Сроки следующего конкурса не объявлены. В 2025 году конкурс анонсирован 5 мая, заявки принимались до 30 сентября 2025; конкурс 2026 года шёл с 13 апреля по 31 мая 2026, заявки — до 24 мая 2026 включительно.', false, array['https://tau-edu.kz/en/events/otkryt-priyem-zayavok-na-konkurs-startapov', 'https://tau-edu.kz/en/events/a-startup-project-competition-tau-innohub-school'], 'Очный или онлайн-формат защиты на странице не указан — команде из Петропавловска стоит уточнить, нужна ли поездка в Астану. Контакт: профессор Константин Шебеко, руководитель Центра предпринимательства (k.shebeko@tau-edu.kz).', false),
  ('startup-orda-sko', 'Startup Orda — региональная инкубация Astana Hub (SKO Hub, Петропавловск)', 'program', 'Astana Hub; в Петропавловске — региональный IT-хаб SKO Hub (филиал АКФ «Астана Хаб»)', array['startup'], 'sko', 10, null, 'По FAQ программы — «все, кто старше 16 лет» (уточнить, допускаются ли ровно 16-летние); нужны ИИН и ЭЦП, намерение запустить проект с IT-составляющей и личное посещение офлайн-занятий. Можно прийти без идеи или с ранним MVP.', 'Индивидуально или командой; размер команды на странице программы не регламентирован.', 'Бесплатно', 'Бесплатная трёхмесячная офлайн-инкубация Astana Hub в региональных IT-хабах: путь от идеи до MVP с трекерами и экспертами; в 2026 году поток проходил и в Петропавловске.', 'Программа идёт через этапы заявки, преинкубации, инкубации и Demo Day: воркшопы, не менее 8 трекинг-сессий на стартап, групповые разборы и консультации экспертов. Темы обучения — Lean Startup, HADI-циклы, SMART-цели, воронки продаж, CRM и CJM, финансовые метрики, венчурный рынок и питч инвесторам; участники получают рабочие места и коворкинг хаба. Лучшие стартапы первого потока 2026 года получают участие в Startup Alley на Digital Bridge и доступ к полуфиналу Astana Hub Battle; финалисты второго потока — Pizza Pitch в Астане, а сильнейшие могут поехать в зарубежный хаб-партнёр. В предыдущем потоке поступило 752 заявки, до финального этапа дошли 205 стартапов. SKO Hub (ул. Жамбыла Жабаева, 195) указывает у себя также Startup School, Startup Academy, No Code и Low Code School и хакатоны, а 15 мая 2026 проводил Startup Orda Open Meet. Для участников клуба 16+ это способ провести свой стартап через настоящую инкубацию, не выезжая из Петропавловска.', 'Подать заявку в личном кабинете astanahub.com при открытии потока в своём регионе (нужны ИИН и ЭЦП); следить за Instagram @sko_hub, Telegram-чатом t.me/it_community_sko и аккаунтом @astana.hub.', 'https://astanahub.com/ru/l/startuporda', null, null, null, null, 'Сроки следующего потока в Петропавловске не объявлены. В 2026: первый поток (Актау, Костанай, Петропавловск, Кокшетау, Актобе, Талдыкорган) — заявки до 25 мая, старт в июне; второй поток стартовал в сентябре 2026 в Шымкенте, Уральске, Семее и Конаеве (без Петропавловска). Длительность — около 3 месяцев.', false, array['https://astanahub.com/ru/l/startuporda', 'https://kapital.kz/tehnology/147259/startap-za-90-dnej-v-kazahstane-startovala-startup-orda.html', 'https://astanahub.com/en/event/startup-orda-open-meet/', 'https://astanahub.com/ru/l/skoithub', 'https://beginit.indrive.com/'], 'Программа не школьная: для несовершеннолетних уточнить в SKO Hub порядок получения ЭЦП и согласие родителей. В анонсах событий SKO Hub для регистрации указывался WhatsApp 8-707-241-77-20. Программа Beginit (inDrive при участии Astana Hub, для 10-классников; отбор раньше проходил и в Петропавловске) приостановлена — на неё не рассчитывать.', false),
  ('sko-hub-internship', 'Стажировка SKO Hub для школьников и студентов', 'internship', 'SKO Hub — региональный IT-хаб СКО (филиал Astana Hub в Петропавловске)', array['ai', 'startup'], 'sko', null, null, 'Школьники и студенты Петропавловска и Северо-Казахстанской области, которые хотят развивать цифровые и творческие навыки. Возраст и классы в публикациях хаба не указаны — уточнять в SKO Hub.', 'Индивидуальное участие; работа в командах над проектами хаба', 'Плата за участие в публикациях не упоминается', 'Годовая практическая стажировка в региональном IT-хабе: стажёры выбирают направление (разработка, GameDev, дизайн, медиа, мероприятия) и решают реальные технологические задачи предпринимателей региона.', 'Стажировка SKO Hub — программа практической подготовки для школьников и студентов СКО, рассчитанная на учебный год. Участники сами выбирают направление: разработка ПО, GameDev, графический дизайн, маркетинг, медиа, организация мероприятий, клубная и волонтёрская деятельность. Стажёры решают практические задачи от предпринимателей региона — веб-сервисы, мобильные продукты, чат-боты, решения на основе ИИ — и собирают портфолио из реальных проектов. Новичков сопровождают старшие стажёры из прошлых потоков, а за любой вклад начисляются баллы в «Таблице активностей», которые можно обменять на призы. В конце года проходит итоговый нетворкинг с вручением сертификатов и номинацией «Стажёр года». По данным хаба, за 2024–2025 год стажировку прошли более 70 участников, которые запустили собственные клубы и организовали хакатон; в потоке 2025–2026 стажёры развивали GameDev-клуб и провели хакатон TECH Future. Специальной подготовки не требуется: полезно прийти с небольшим проектом или идеей, чтобы быстрее выбрать направление.', 'Обратиться в SKO Hub лично (Петропавловск, ул. Жамбыла Жабаева, 195) или через Instagram @sko_hub и уточнить, идёт ли ещё набор в поток 2026–2027.', 'https://astanahub.com/ru/l/skoithub', null, null, null, null, 'В публикации SKO Hub от 05.06.2026 сказано, что следующий поток стажировки стартует в сентябре 2026 года; точная дата старта и сроки набора не опубликованы. Пост о старте предыдущего потока (2025–2026) вышел 29.10.2025.', false, array['https://astanahub.com/ru/blog/v-sko-hub-startoval-novyi-potok-stazhirovki-2025-20261761210477', 'https://astanahub.com/ru/blog/v-sko-hub-sostoialsia-networking-posviashchennyi-podvedeniiu-itogov-stazhirovki-2025-2026-uchebnogo-goda', 'https://astanahub.com/ru/l/skoithub'], 'Самая доступная регулярная офлайн-возможность в Петропавловске для участников клуба. Отдельной онлайн-анкеты в открытом доступе не найдено — набор, судя по публикациям, идёт через сам хаб.', false),
  ('sko-hub-career-map', 'Career Map — профориентационные встречи по IT в SKO Hub', 'event', 'SKO Hub (филиал Astana Hub в Петропавловске)', array['ai', 'algo', 'startup'], 'sko', null, null, 'Школьники и студенты Петропавловска и Северо-Казахстанской области; возрастных ограничений в публикации нет.', 'Индивидуально или группой; формат записи уточнять у хаба', 'Плата в публикации не упоминается', 'Регулярные (по средам) профориентационные встречи в формате интерактивного квеста: IT-профессии, искусственный интеллект, стажировки и образовательные программы хаба.', 'Career Map — профориентационная программа SKO Hub, которая реализуется в рамках Года цифровизации и искусственного интеллекта. На встречах участники знакомятся с инфраструктурой и направлениями работы хаба, узнают о развитии ИИ, востребованных цифровых навыках и актуальных профессиях в IT — всё это в формате интерактивного квеста. Отдельно рассказывают о возможностях обучения, стажировок, образовательных программ и технологических проектов. Участникам дают практические советы: с чего начать путь в IT, какие компетенции нужны на рынке и как ИИ меняет профессии. По данным хаба, встречи проходят каждую среду. Для клуба это удобный формат выездного занятия: после встречи можно сразу узнать о стажировке и ближайших питч-сессиях хаба. Подготовка не нужна — достаточно заранее сформулировать вопросы о профессиях и стажировках.', 'Договориться о визите с SKO Hub (ул. Жамбыла Жабаева, 195) лично или через Instagram @sko_hub; для группы из школы или клуба дату лучше согласовать заранее.', 'https://astanahub.com/ru/blog/shkolniki-i-studenty-petropavlovska-znakomiatsia-s-karernymi-vozmozhnostiami-v-sfere-it', null, null, null, null, 'Регулярный формат: в публикации филиала Astana Hub в Петропавловске от 29.05.2026 сказано, что встречи проходят каждую среду. Продолжение программы в 2026–2027 учебном году и точное время встреч не подтверждены — уточнять в хабе.', false, array['https://astanahub.com/ru/blog/shkolniki-i-studenty-petropavlovska-znakomiatsia-s-karernymi-vozmozhnostiami-v-sfere-it'], 'Хорошо подходит младшим участникам (7–9 классы) как первое знакомство с IT-экосистемой города.', false),
  ('sko-hub-pizza-pitch', 'PIZZA PITCH by SKO Hub — питч IT-идей', 'startup', 'SKO Hub (филиал Astana Hub в Петропавловске)', array['startup', 'ai'], 'sko', null, null, 'Все, у кого есть идея IT-продукта; готовый бизнес не нужен, прототип или MVP — преимущество. Возрастных ограничений в анонсе нет — школьникам стоит заранее уточнить у организаторов условия участия несовершеннолетних.', 'В анонсе не уточняется (индивидуально или командой)', 'Плата за участие в анонсе не упоминается', 'Конкурс питчей в SKO Hub: презентуй экспертам идею цифрового продукта, получи обратную связь и поборись за 150 000 ₸.', 'PIZZA PITCH — питч-сессия SKO Hub, на которой участники коротко презентуют идею IT-продукта экспертам. Подходит любая цифровая идея: AI-сервис, мобильное приложение, веб-платформа, чат-бот, информационная система или другой IT-продукт. Готовый бизнес не обязателен — достаточно идеи и понимания проблемы, которую она решает; прототип или MVP даёт преимущество. Заявки принимаются до 13 октября, финальный питч проходит 16 октября в SKO Hub. Участники борются за 150 000 ₸ и получают обратную связь от экспертов. Для подготовки: сформулируйте проблему и целевого пользователя, сделайте 3–5 слайдов и, если есть, покажите демо или кликабельный прототип.', 'Подать заявку через страницу мероприятия на astanahub.com (организатор — Филиал АКФ Астана хаб по г. Петропавловск) до 13 октября; финал — в SKO Hub, ул. Жамбыла Жабаева, 195.', 'https://astanahub.com/ru/event/pizza-pitch-by-sko-hub1791435539', 'https://astanahub.com/ru/event/pizza-pitch-by-sko-hub1791435539', date '2026-10-13', date '2026-10-16', date '2026-10-16', 'Страница мероприятия на astanahub.com: приём заявок до 13 октября, финальный питч 16 октября в 16:00; в карточке события указано 16.10.2026, 15:00–19:00.', true, array['https://astanahub.com/ru/event/pizza-pitch-by-sko-hub1791435539', 'https://astanahub.com/ru/event/'], '10.2026 до дедлайна 3 дня. Хороший первый публичный питч для трека «стартап-инженерия».', false),
  ('idea-battle', 'IDEA BATTLE — питч-сессии IT-идей SKO Hub и СКУ им. М. Козыбаева', 'startup', 'SKO Hub и Центр искусственного интеллекта и цифровой трансформации СКУ им. М. Козыбаева (Kozybayev University)', array['startup', 'ai'], 'sko', null, null, 'Открытый формат: в марте 2026 года участвовали студенты СКУ, школьники и резиденты SKO Hub; первое место заняла школьная команда Назарбаев Интеллектуальной школы Петропавловска.', 'Командой или индивидуально', 'Плата в анонсах не упоминается', 'Битвы идей: команды коротко питчат IT-проекты перед экспертами и аудиторией, получают обратную связь, дипломы и подарки.', 'IDEA BATTLE — формат коротких питчей IT-идей с обратной связью от предпринимателей, экспертов и зрителей. 22 ноября 2025 года он прошёл в SKO Hub как открытая неформальная питч-сессия, а 18 марта 2026 года — как IDEA BATTLE by KU & SKO Hub на базе Центра искусственного интеллекта и цифровой трансформации СКУ в рамках Digital Nauryz 2026. В мартовском конкурсе выступили 10 команд со стартап-идеями для бизнеса, медицины, изучения языков, борьбы с мошенничеством и других сфер. Проекты оценивало жюри из представителей госструктур, бизнеса, диджитал-экспертов, специалистов по нейросетям и педагогов. Первое место заняла школьная команда НИШ Петропавловска с ИИ-сервисом EDU WAY, который помогает абитуриентам выбрать вуз и стажировку. Для участия стоит подготовить 2–3-минутный питч с описанием проблемы, решения и, по возможности, демо.', 'Следить за анонсами SKO Hub на astanahub.com и в Instagram @sko_hub, а также за новостями ku.edu.kz; регистрация — по ссылке в анонсе конкретного выпуска.', 'https://astanahub.com/ru/event/idea-battle-by-ku-sko-hub', null, null, null, null, 'Прошедшие выпуски: 22.11.2025 (SKO Hub) и 18.03.2026 (СКУ, Digital Nauryz 2026). Даты следующего выпуска в 2026–2027 учебном году не объявлены.', false, array['https://astanahub.com/ru/event/idea-battle-by-ku-sko-hub', 'https://astanahub.com/ru/event/idea-battle-v-sko-hub/', 'https://ku.edu.kz/ru/news/13171', 'https://ku.edu.kz/ru/news/12586'], 'Отдельной IT-программы СКУ для школьников (кружка, летней школы, олимпиады) найти не удалось; IDEA BATTLE — единственная найденная IT-активность университета, где выступают школьники. Кроме того, СКУ проводит дни открытых дверей для старшеклассников, а в мае 2025 года выдал собственные гранты на обучение 14 выпускникам школ СКО — победителям и призёрам республиканских олимпиад и республиканского конкурса научных проектов.', false),
  ('tomorrow-school', 'Tomorrow School в Петропавловске (на базе СКУ им. М. Козыбаева) — только 18+', 'program', 'Astana Hub и фонд Alem.ai (платформа 01 Edu); площадка — СКУ им. М. Козыбаева', array['ai', 'algo'], 'sko', null, null, 'Только с 18 лет. Опыт программирования и диплом не нужны. Для участников клуба — вариант после окончания школы.', 'Индивидуально (обучение peer-to-peer в общем кампусе)', 'Бесплатно', 'Бесплатная школа программирования и искусственного интеллекта без преподавателей и лекций (модель peer-to-peer 01 Edu), открытая в Петропавловске на базе СКУ; принимает только с 18 лет.', 'Tomorrow School — сеть бесплатных школ программирования и ИИ от Astana Hub и фонда Alem.ai на платформе 01 Edu; в апреле 2026 года открылись 14 площадок по стране, включая Kozybayev University в Петропавловске. Обучение очное и без привычных лекций и расписания: студенты выполняют проекты, учат друг друга и проверяют код. Отбор: онлайн-игры на память и логику (Memory и 90-минутный Zzle), анкета, check-in встреча и 4-недельный интенсив «Бассейн». Затем — 18 месяцев основного обучения (JavaScript, Go, Rust, Python, технологии ИИ, более 50 проектов), 3 месяца стажировки в IT-компаниях и 6 месяцев специализации (AI/ML, кибербезопасность, GameDev, мобильная разработка, Cloud DevOps, блокчейн, fullstack). На первый набор в Петропавловске подали 180 заявок, отобрали около 60 участников. Школьникам до 18 лет участвовать нельзя, но готовиться можно заранее: задачи на логику и первые проекты на JavaScript или Python.', 'Подать заявку на tomorrow-school.ai: пройти логические игры, заполнить анкету, после её подтверждения записаться на check-in и пройти «Бассейн».', 'https://tomorrow-school.ai/', 'https://tomorrow-school.ai/', null, null, null, 'Площадка в СКУ начала работу в конце августа 2026 года (новость ku.edu.kz от 28.08.2026); сроки следующих наборов на официальном сайте не опубликованы.', false, array['https://tomorrow-school.ai/', 'https://ku.edu.kz/ru/news/13428', 'https://ku.edu.kz/ru/news/13277'], 'Возрастное правило: строго 18+ (FAQ официального сайта: «любой человек старше 18 лет»). FAQ сайта описывает обучение на территории Astana Hub (павильон C4.6) — это астанинский кампус; в Петропавловске занятия идут на базе СКУ.', false),
  ('tumo-astana', 'TUMO Astana — бесплатный центр креативных технологий для подростков', 'program', 'Фонд Alem.ai Foundation под управлением Astana Hub и МИИЦР РК, по модели международной сети TUMO', array['ai'], 'kz', 7, 12, 'Подростки 12–18 лет, без вступительных требований, обучение с нуля. Если участнику нет 18, анкету заполняет родитель или законный представитель. Занятия очные в Астане.', 'Индивидуально (воркшопы в группах)', 'Бесплатно', 'Бесплатное очное обучение в Астане по 11 направлениям — от генеративного ИИ и программирования до разработки игр и робототехники — с итоговым портфолио проектов.', 'TUMO Astana — первый в Центральной Азии центр международной сети TUMO, открытый в апреле 2026 года в Международном центре искусственного интеллекта alem.ai в Астане; рассчитан на обучение до 5 000 подростков в год. Доступны 11 технических и креативных направлений: генеративный ИИ, программирование, разработка игр, анимация, 3D-моделирование, робототехника, графический и моушн-дизайн, веб-разработка, кинопроизводство и цифровая музыка. Модель обучения сочетает самостоятельные занятия на платформе TUMO World, практические воркшопы с профессионалами индустрии и продвинутые лаборатории MasterLabs для самых мотивированных. По итогам ученик собирает цифровое портфолио реализованных проектов. Места ограничены и распределяются в порядке регистрации, регистрация не гарантирует зачисление. После заявки команда TUMO приглашает на вводную встречу, куда нужно прийти с удостоверениями ученика и родителя.', 'Заполнить онлайн-форму по ссылке на странице astana.tumo.kz/enroll-now (для младше 18 лет — заполняет родитель), выбрать удобное время занятий и дождаться приглашения на вводную встречу.', 'https://astana.tumo.kz/enroll-now/', 'https://astana.tumo.kz/enroll-now/', null, null, null, 'Набор непрерывный, места распределяются по мере регистрации; фиксированных сроков на сайте нет. Центр открыт в апреле 2026 года (новость Astana Hub от 24.04.2026).', false, array['https://astana.tumo.kz/enroll-now/', 'https://astanahub.com/ru/article/v-astane-otkrylsia-pervyi-v-tsentralnoi-azii-tsentr-kreativnykh-tekhnologii-tumo'], 'Для Петропавловска реально только при проживании в Астане: занятия очные, онлайн-формат не упоминается. Astana Hub анонсировал филиалы в Алматы, Актобе и Акмолинской области и формат TUMO Classroom в регионах — стоит следить за запуском в СКО. Адрес: Астана, пр. Мәңгілік Ел, 55/8, павильон 4.6; телефон +7 775 903 4013.', false),
  ('samsung-innovation-campus', 'Samsung Innovation Campus — бесплатная IT-школа (ИИ, Python и Big Data, мобильная разработка)', 'course', 'Samsung Electronics (Samsung Kazakhstan)', array['ai', 'algo'], 'online', 7, 12, 'Школьники и студенты 13–25 лет (у отдельных курсов могут быть свои возрастные ограничения). Нужно сдать вступительный тест (проходной балл 40). Для курса мобильной разработки нужен компьютер (не слабее Intel Core i5, 8 ГБ ОЗУ) и Android-устройство.', 'Индивидуально', 'Бесплатно', 'Бесплатные курсы Samsung для 13–25 лет: основы ИИ и машинного обучения, Python и Big Data, мобильная разработка на Java — очно в шести городах или онлайн через Google Meet, с сертификатом Samsung.', 'Samsung Innovation Campus работает в Казахстане с декабря 2017 года и бесплатно обучает школьников и студентов 13–25 лет. В 2026–2027 учебном году доступны три курса: «Основы искусственного интеллекта и машинного обучения», «Основы Python и Big Data» (анализ данных, 4–4,5 месяца) и «Мобильная разработка» на Java (до 10 месяцев, включая модуль по алгоритмам и структурам данных). Занятия идут 2–3 раза в неделю по ~120 минут — очно в классах (Алматы, Астана, Актобе, Атырау, Талдыкорган, Костанай) или онлайн через Google Meet; в ряде локаций есть обучение на казахском. Домашние задания обязательны, знания проверяются тестовыми экзаменами. В конце курса — дипломный проект (своё мобильное приложение или набор задач по анализу данных), успешные выпускники получают сертификат Samsung Electronics. Порядок поступления: регистрация, выбор курса, вступительный экзамен, выбор группы в личном кабинете; если мест нет, можно встать во «Временную группу» ожидания.', 'Зарегистрироваться на samsung-campus.kz в период набора, выбрать курс и онлайн-формат, сразу сдать вступительный тест и выбрать группу в личном кабинете.', 'https://samsung-campus.kz/', 'https://samsung-campus.kz/', date '2026-09-25', date '2026-09-26', null, 'Новость на samsung-campus.kz от 15.09.2026: регистрация открыта до 25 сентября, начало учёбы — 26 сентября 2026 года. На 10 октября 2026 этот набор закрыт; даты следующего набора не объявлены (для опоздавших и при нехватке мест предусмотрена «Временная группа» ожидания).', true, array['https://samsung-campus.kz/news/2026-27_academic_year_began', 'https://samsung-campus.kz/', 'https://samsung-campus.kz/tracks', 'https://samsung-campus.kz/classrooms'], 'Возраст 13–25 — подходит школьникам. Очных классов в СКО нет, для Петропавловска — онлайн-формат. Стоит подписаться на новости сайта и Telegram-канал проекта, чтобы не пропустить следующий набор.', false),
  ('acts-cpfed', 'ACTS x CPFED — учебно-тренировочные сборы по спортивному программированию', 'camp', 'Федерация спортивного программирования Казахстана (CPFED) при поддержке JetBrains Foundation; площадка 2026 года — Astana IT University', array['algo'], 'kz', 8, 11, 'Трек Early Talent: школьники Казахстана (граждане или резиденты РК, обучающиеся в школе РК), не в выпускном классе. Возраст по условиям участия — от 14 лет до 19 лет (на странице CPFED указано 16–19, на лендинге JetBrains — 14–18; расхождение уточнять). Отбор: результаты Республиканской олимпиады по информатике (70%) и вступительный контест с прокторингом (30%). Национальные сборные IOI приглашаются отдельно.', 'Индивидуально', 'Стоимость участия и покрытие проезда и проживания на официальных страницах не указаны', 'Почти двухнедельные очные сборы для сильных олимпиадников: интенсивные контесты, разборы и тренировки вместе со сборными IOI стран Центральной Азии; до 20 мест для молодых талантов из Казахстана.', 'Algorithm and Code Training School (ACTS) — серия тренировочных лагерей по спортивному программированию при поддержке JetBrains Foundation; в 2026 году лагерь прошёл в Казахстане совместно с CPFED (3–15 июля, Astana IT University, язык обучения — английский). В программе — лекции, контесты в формате IOI, командные и эвристические соревнования и обратная связь от экспертов мирового уровня. Вместе с молодыми талантами тренировались национальные сборные IOI Казахстана, Узбекистана, Азербайджана, Кыргызстана, Таджикистана и Туркменистана. Для казахстанских школьников было до 20 мест; в отборе на 70% учитывался результат Республиканской олимпиады по информатике и на 30% — вступительный контест с прокторингом (запись экрана и веб-камеры через OBS). При регистрации нужен хэндл Codeforces; любая посторонняя помощь, включая ИИ, ведёт к дисквалификации. Готовиться стоит через регулярные раунды Codeforces и этапы олимпиады по информатике.', 'Следить за разделом «Учебно-тренировочные сборы» на cpfed.kz; в 2026 году регистрация шла через лендинг JetBrains Academy, затем проводился вступительный контест.', 'https://cpfed.kz/ru/projects/training/camps', null, null, null, null, 'Цикл 2026 завершён: регистрация до 25.04.2026, сборы 3–15.07.2026 в Астане. О выпуске 2027 года ничего не объявлено; прошлые выпуски ACTS проходили в Румынии (2024) и Сербии (2025), так что место следующего лагеря неизвестно.', false, array['https://cpfed.kz/ru/projects/training/camps', 'https://lp.jetbrains.com/academy/acts/cpfed/2026/', 'https://cpfed.kz/projects/training/camps/terms-and-conditions'], 'Только для сильных участников трека алгоритмов: решающий фактор отбора — результат Республиканской олимпиады по информатике. В анкете спрашивают об интересе к полной стипендии JetBrains Foundation в Constructor University Bremen и Neapolis University Pafos.', false),
  ('jetbrains-csai-scholarship', 'Стипендия JetBrains Foundation — бакалавриат Computer Science and AI в Neapolis University Pafos (Кипр)', 'grant', 'JetBrains Foundation / JetBrains Academy и Neapolis University Pafos', array['ai', 'algo'], 'intl', 11, 12, 'Выпускники школ с сильной школьной математикой и базовым знанием хотя бы одного языка программирования. Нужны аттестат (или прогнозные оценки) и сертификат по английскому; если получить сертификат в своей стране нельзя, можно подать без него. Ограничений по возрасту и гражданству на странице нет.', 'Индивидуально', 'Плата за подачу на странице не упоминается. Стипендия покрывает обучение, проживание, медстраховку, визовый сбор и около 300 € в месяц; без стипендии — 6 000 € в год за обучение плюс 2 000–6 000 € в год за проживание', 'Полностью оплаченный англоязычный бакалавриат по компьютерным наукам и ИИ на Кипре — в 2026 году до 40 стипендий; отбор через вступительный тест по математике и информатике и интервью.', 'JetBrains Academy вместе с Neapolis University Pafos (Кипр) ведёт англоязычный бакалавриат Computer Science and Artificial Intelligence (CSAI). Стипендия JetBrains Foundation покрывает обучение, проживание, медицинскую страховку, визовый сбор (если нужен) и выплачивает около 300 € в месяц; в 2026 году было до 40 стипендиальных мест и до 10 платных. Все поступающие автоматически рассматриваются на стипендию. Этапы: пакет документов (паспорт, рекомендательное письмо, мотивационное письмо до 500 слов, CV, аттестат или прогнозные оценки, сертификат по английскому), 4-часовой вступительный тест (10 задач по математике и 6 по информатике), 40-минутное интервью для лучших и решение о стипендии. Для подготовки есть пробный тест и материалы на сайте программы. Сильнее всего помогает олимпиадная математика, алгоритмические задачи и английский.', 'Следить за открытием приёма на 2027 год на странице программы (можно оставить контакты в лид-форме), затем отправить анкету с документами на e-mail, указанный на странице, и пройти тест и интервью.', 'https://lp.jetbrains.com/csai-program/how-to-apply/', null, null, null, null, 'Приём на 2026 год закрыт (раунды: заявки до 28.04.2026 и до 09.06.2026). Сроки приёма на 2027 год на официальной странице не опубликованы.', false, array['https://lp.jetbrains.com/csai-program/how-to-apply/', 'https://cpfed.kz/projects/training/camps/terms-and-conditions'], 'Актуально для 11–12 классов (выпускников 2027 года). Аналогичная стипендия JetBrains Foundation есть в Constructor University Bremen (упоминается в условиях сборов ACTS x CPFED), её условия здесь не проверялись. В 2026 году раунды подачи шли в апреле и июне — готовиться стоит заранее.', false),
  ('hack-club', 'Hack Club — международное сообщество и бесплатные программы для подростков, которые делают проекты', 'program', 'Hack Club (The Hack Foundation, некоммерческая организация, США)', array['startup', 'ai'], 'online', 7, 12, 'Любые подростки 13–18 лет из любой страны.', 'Индивидуально, командой или школьным клубом', 'Бесплатно', 'Крупнейшее некоммерческое движение подростков-мейкеров: онлайн-сообщество в Slack, сменяющиеся бесплатные программы и хакатоны, сеть школьных клубов и платформа HCB для финансов подростковых событий.', 'Hack Club объединяет подростков 13–18 лет со всего мира, которые создают собственные проекты — от игр и сайтов до электроники. Участники общаются в онлайн-сообществе в Slack, где постоянно анонсируются новые программы; на странице программ собраны текущие события, бесплатные и открытые для любого подростка. В мире работает более 1 500 очных Hack Club в школах: можно найти клуб рядом или зарегистрировать свой и получить помощь с запуском. Платформа HCB позволяет командам подростков собирать пожертвования и вести финансы своих хакатонов и клубов под эгидой некоммерческой организации; ею пользуются более 700 команд. За участие открываются бесплатные бонусы (GitHub Education, Brilliant Premium и другие). Для старта достаточно вступить в Slack и выбрать программу, в которой нужно сделать и показать свой проект.', 'Нажать «Join» на hackclub.com и вступить в Slack-сообщество; текущие программы — на hackclub.com/programs; регистрация школьного клуба — в разделе Clubs.', 'https://hackclub.com/', 'https://hackclub.com/programs/', null, null, null, 'Постоянное сообщество без единого дедлайна; конкретные программы меняются, у каждой свои сроки — смотреть на hackclub.com/programs.', false, array['https://hackclub.com/', 'https://hackclub.com/programs/'], 'AIT Club может зарегистрироваться как Hack Club и получить ресурсы и выход на международное сообщество. Всё общение на английском. Доставку физических призов и использование HCB из Казахстана нужно проверять для каждой программы отдельно.', false),
  ('beginit', 'Beginit Central Asia by inDrive — программа социального лидерства для 10-классников', 'program', 'inDrive (Beginit Central Asia); в СКО — при поддержке SKO Hub', array['startup'], 'kz', 10, 10, 'Ученики 10 класса из регионов проекта. В 2024 году СКО участвовала впервые, отбор прошёл в Петропавловске. Состав регионов и условия нового сезона не подтверждены.', 'Индивидуальный отбор, затем работа над социальными проектами', 'Плата в публикации не упоминается', 'Отбор, образовательный модуль и менторство для 10-классников, которые хотят запускать социальные проекты в своём регионе; финалисты получают приглашения в inVision U, поездки, курсы подготовки к ЕНТ и ноутбуки.', 'Beginit Central Asia by inDrive — социально-образовательная программа для 10-классников из регионов Казахстана. 1 октября 2024 года отборочный тур в СКО прошёл в СКУ им. М. Козыбаева и собрал более 100 школьников; задания выявляли лидерские качества, участники обсуждали идеи решения проблем региона. Лучшие проходят образовательный модуль по основам социального лидерства, разрабатывают проекты для улучшения жизни в своих регионах и могут посетить инновационные центры Astana Hub. SKO Hub предоставлял участникам площадку и менторскую поддержку. Лучшие финалисты получают приглашения на Foundation Year в университете inVision U и могут выиграть образовательные поездки за границу, курсы подготовки к ЕНТ и ноутбуки. Для отбора полезно заранее продумать проблему своего города и идею проекта.', 'Следить за анонсами Beginit и SKO Hub в начале учебного года; в 2024 году отбор проходил очно в региональном туре (в СКО — на базе СКУ).', 'https://astanahub.com/ru/article/shkolnikov-sko-obuchat-navykam-sotsialnogo-liderstva', null, null, null, null, 'Данных о сезоне 2026–2027 не найдено. В 2024 году отбор в СКО прошёл 1 октября на базе СКУ им. М. Козыбаева.', false, array['https://astanahub.com/ru/article/shkolnikov-sko-obuchat-navykam-sotsialnogo-liderstva', 'https://astanahub.com/ru/l/skoithub'], 'Скрыто от участников: по данным на октябрь 2026 программа, вероятно, приостановлена. Откройте запись, когда объявят новый набор. Актуальность программы на 2026–2027 не подтверждена — уточните у SKO Hub. Не IT-программа в узком смысле, но полезна треку «стартап-инженерия» (проектная работа над проблемами региона).', true)
on conflict (key) do nothing;
